import { NextResponse } from "next/server";

import {
  isGoogleAppConfigured,
  putGoogleAppConfig,
} from "@/lib/integrations/google/app-config";
import { parseGoogleAppConfig } from "@/lib/integrations/google/app-config-core";
import { createSupabaseAdminClient } from "@/lib/supabase/admin";
import { createSupabaseServerClient } from "@/lib/supabase/server";

export const runtime = "nodejs";

export async function GET(request: Request) {
  const access = await requireAgencyAdmin(request);
  if ("error" in access) return json({ error: access.error }, access.status);

  return json({ configured: await isGoogleAppConfigured() });
}

export async function POST(request: Request) {
  const access = await requireAgencyAdmin(request);
  if ("error" in access) return json({ error: access.error }, access.status);

  let config;
  try {
    const body = await request.json();
    config = parseGoogleAppConfig(body);
  } catch (error) {
    return json(
      { error: error instanceof Error ? error.message : "Invalid Google application configuration." },
      400,
    );
  }

  try {
    await putGoogleAppConfig(config);
    return json({ configured: true, message: "Google application configuration saved securely." });
  } catch (error) {
    return json(
      {
        error: error instanceof Error
          ? error.message
          : "Unable to save Google application configuration.",
      },
      500,
    );
  }
}

async function requireAgencyAdmin(request: Request) {
  const bearerToken = request.headers.get("authorization")
    ?.match(/^Bearer\s+(.+)$/i)?.[1];
  const authClient = bearerToken
    ? createSupabaseAdminClient()
    : await createSupabaseServerClient();
  const { data: authData, error: authError } = await authClient.auth.getClaims(bearerToken);
  const userId = authData?.claims?.sub;

  if (authError || !userId) {
    return { error: "Authentication required. Please sign in again.", status: 401 as const };
  }

  const admin = createSupabaseAdminClient();
  const { data: user, error } = await admin
    .from("users")
    .select("role")
    .eq("id", userId)
    .maybeSingle();

  if (error) return { error: error.message, status: 500 as const };
  if (!user || !["super_admin", "agency_admin"].includes(user.role)) {
    return { error: "Agency administrator access is required.", status: 403 as const };
  }

  return { userId };
}

function json(body: Record<string, unknown>, status = 200) {
  return NextResponse.json(body, {
    status,
    headers: { "Cache-Control": "private, no-store" },
  });
}

import "server-only";

import { createHash } from "node:crypto";
import { NextResponse } from "next/server";

import { requireIntegrationConnection } from "@/lib/integrations/access";

export const runtime = "nodejs";

const ROBAWS_CLIENTS_URL =
  "https://app.robaws.com/api/v2/clients?page=0&size=1";

export async function GET(request: Request) {
  const companyId = new URL(request.url).searchParams.get("companyId") ?? "";

  if (!companyId) {
    return json({ error: "companyId is required." }, 400);
  }

  const access = await requireIntegrationConnection(companyId, "robaws");

  if ("error" in access) {
    return json({ error: access.error }, access.status);
  }

  const key = process.env.ROBAWS_API_KEY ?? "";
  const secret = process.env.ROBAWS_API_SECRET ?? "";
  let robawsHttpStatus: number | null = null;
  let robawsOk = false;

  try {
    const response = await fetch(ROBAWS_CLIENTS_URL, {
      headers: {
        Accept: "application/json",
        Authorization: `Basic ${Buffer.from(`${key}:${secret}`).toString("base64")}`,
      },
      cache: "no-store",
    });

    robawsHttpStatus = response.status;
    robawsOk = response.ok;
  } catch {
    // Network failures intentionally expose no detail that could include credentials.
  }

  return json({
    VERCEL_ENV: process.env.VERCEL_ENV ?? null,
    VERCEL_GIT_COMMIT_SHA: process.env.VERCEL_GIT_COMMIT_SHA ?? null,
    keyPresent: key.length > 0,
    keyLength: key.length,
    keySha256Prefix: sha256Prefix(key),
    secretPresent: secret.length > 0,
    secretLength: secret.length,
    secretSha256Prefix: sha256Prefix(secret),
    robawsHttpStatus,
    robawsOk,
  });
}

function sha256Prefix(value: string) {
  return value
    ? createHash("sha256").update(value).digest("hex").slice(0, 12)
    : null;
}

function json(body: Record<string, unknown>, status = 200) {
  return NextResponse.json(body, {
    status,
    headers: { "Cache-Control": "private, no-store" },
  });
}

import { NextResponse } from "next/server";
import { requireIntegrationConnection } from "@/lib/integrations/access";
import { missingProviderConfiguration, parseProvider, providerCatalog } from "@/lib/integrations/catalog";
import { credentialStore } from "@/lib/integrations/credentials";
import { buildAuthorizationUrl } from "@/lib/integrations/oauth";
import { createOAuthState } from "@/lib/integrations/oauth-state";
import { validateRobawsCredentials } from "@/lib/integrations/robaws-client";
import { ensureWebsiteFormsCredential } from "@/lib/integrations/website-forms";

export const runtime = "nodejs";

export async function GET(
  request: Request,
  { params }: { params: Promise<{ provider: string }> },
) {
  const provider = parseProvider((await params).provider);

  if (!provider) {
    return NextResponse.json(
      { error: "Unknown integration provider." },
      { status: 404 },
    );
  }

  const companyId =
    new URL(request.url).searchParams.get("companyId") ?? "";

  if (!companyId) {
    return NextResponse.json(
      { error: "companyId is required." },
      { status: 400 },
    );
  }

  const access = await requireIntegrationConnection(companyId, provider);

  if ("error" in access) {
    return NextResponse.json(
      { error: access.error },
      { status: access.status },
    );
  }

  const missing = await missingProviderConfiguration(provider);

  if (missing.length) {
    return NextResponse.json(
      {
        error:
          `${providerCatalog[provider].name} is not configured yet. ` +
          `Missing server settings: ${missing.join(", ")}.`,
      },
      { status: 503 },
    );
  }

  const definition = providerCatalog[provider];

  if (provider === "website_forms") {
    try {
      const credential = await ensureWebsiteFormsCredential(
        access.connection.id,
        credentialStore,
      );
      const now = new Date().toISOString();
      const { error } = await access.supabase
        .from("reporting_integration_connections")
        .update({
          configuration: { endpoint_name: "/api/leads/ingest" },
          status: "connected",
          error_message: null,
          updated_at: now,
        })
        .eq("id", access.connection.id);

      if (error) {
        return NextResponse.json(
          { error: error.message },
          { status: 500 },
        );
      }

      return NextResponse.json({
        message: credential.created
          ? "Website forms connected. Rotate the signing secret to retrieve a one-time value for the website server."
          : "Website forms reconnected using the existing signing secret.",
        secretCreated: credential.created,
      });
    } catch (error) {
      return NextResponse.json(
        {
          error: error instanceof Error
            ? error.message
            : "Unable to configure Website forms.",
        },
        { status: 500 },
      );
    }
  }

  if (definition.auth === "server_token") {
    const now = new Date().toISOString();

    if (provider === "robaws") {
      try {
        await validateRobawsCredentials();
      } catch (error) {
        const message =
          error instanceof Error
            ? error.message
            : "ROBAWS credential validation failed.";

        const { error: saveError } = await access.supabase
          .from("reporting_integration_connections")
          .update({
            status: "error",
            error_message: message,
            updated_at: now,
          })
          .eq("id", access.connection.id);

        if (saveError) {
          return NextResponse.json(
            {
              error:
                `${message} Unable to save the connection error: ${saveError.message}`,
            },
            { status: 500 },
          );
        }

        return NextResponse.json(
          { error: message },
          { status: 502 },
        );
      }
    }

    const { error } = await access.supabase
      .from("reporting_integration_connections")
      .update({
        status: "connected",
        error_message: null,
        updated_at: now,
      })
      .eq("id", access.connection.id);

    if (error) {
      return NextResponse.json(
        { error: error.message },
        { status: 500 },
      );
    }

    return NextResponse.json({
      message: `${definition.name} connected using the configured server credential.`,
    });
  }

  if (process.env.OAUTH_TOKEN_STORAGE_REVIEWED !== "true") {
    return NextResponse.json(
      {
        error:
          "OAuth is prepared but intentionally disabled until private token storage has completed security review.",
      },
      { status: 503 },
    );
  }

  const origin = new URL(request.url).origin;
  const redirectUri =
    `${origin}/api/integrations/${provider}/callback`;

  const state = createOAuthState({
    companyId,
    provider,
    userId: access.user.id,
  });

  const authorizationUrl =
    await buildAuthorizationUrl(provider, redirectUri, state);

  const { error } = await access.supabase
    .from("reporting_integration_connections")
    .update({
      status: "connecting",
      error_message: null,
      updated_at: new Date().toISOString(),
    })
    .eq("id", access.connection.id);

  if (error) {
    return NextResponse.json(
      { error: error.message },
      { status: 500 },
    );
  }

  return NextResponse.json({ authorizationUrl });
}

import { NextResponse } from "next/server";

import { requireIntegrationConnection } from "@/lib/integrations/access";
import {
  parseProvider,
  providerCatalog,
} from "@/lib/integrations/catalog";
import { credentialStore } from "@/lib/integrations/credentials";
import {
  exchangeAuthorizationCode,
} from "@/lib/integrations/oauth";
import {
  verifyOAuthState,
} from "@/lib/integrations/oauth-state";
import { parseMetaPermissionRows } from "@/lib/integrations/meta/production-core";

export const runtime = "nodejs";

const googleProviders = [
  "google_ads",
  "ga4",
  "search_console",
  "google_business",
] as const;

const incompleteAuthorizationMessage =
  "Authorization was cancelled or incomplete.";

export async function GET(
  request: Request,
  {
    params,
  }: {
    params: Promise<{ provider: string }>;
  },
) {
  const provider = parseProvider((await params).provider);

  if (!provider) {
    return NextResponse.json(
      { error: "Unknown integration provider." },
      { status: 404 },
    );
  }

  const url = new URL(request.url);
  const stateValue = url.searchParams.get("state");
  const code = url.searchParams.get("code");
  const providerReportedError = [
    "error",
    "error_reason",
    "error_description",
  ].some((parameter) => url.searchParams.has(parameter));

  if (!stateValue) {
    return NextResponse.redirect(
      new URL(
        `/integrations?integration_error=${encodeURIComponent(incompleteAuthorizationMessage)}`,
        url.origin,
      ),
    );
  }

  let resetConnection:
    | ((message: string) => Promise<void>)
    | null = null;

  try {
    const state = verifyOAuthState(stateValue);

    if (state.provider !== provider) {
      throw new Error("Provider mismatch in OAuth state.");
    }

    const access = await requireIntegrationConnection(
      state.companyId,
      provider,
    );

    if (
      "error" in access ||
      access.user.id !== state.userId
    ) {
      throw new Error(
        "The authorization session is no longer valid.",
      );
    }

    if (provider === "meta") {
      resetConnection = async (message: string) => {
        const { error } = await access.supabase
          .from("reporting_integration_connections")
          .update({
            status: "not_connected",
            error_message: message,
            updated_at: new Date().toISOString(),
          })
          .eq("id", access.connection.id)
          .eq("company_id", state.companyId)
          .eq("provider", provider)
          .select("id")
          .single();

        if (error) {
          throw new Error(
            `Unable to reset the cancelled authorization: ${error.message}`,
          );
        }
      };
    }

    if (!code || (provider === "meta" && providerReportedError)) {
      if (resetConnection) {
        await resetConnection(incompleteAuthorizationMessage);
      }

      return NextResponse.redirect(
        new URL(
          `/integrations?integration_error=${encodeURIComponent(incompleteAuthorizationMessage)}`,
          url.origin,
        ),
      );
    }

    if (!credentialStore.ready) {
      throw new Error(
        "Secure credential storage is unavailable.",
      );
    }

    const existingCredential =
      await credentialStore.read(
        access.connection.id,
        provider,
      );

    const redirectUri =
      `${url.origin}/api/integrations/${provider}/callback`;

    const credential =
      await exchangeAuthorizationCode(
        provider,
        code,
        redirectUri,
        stateValue,
        existingCredential,
      );

    const group =
      providerCatalog[provider].authorizationGroup;

    if (group === "google") {
      const {
        data: connections,
        error: connectionsError,
      } = await access.supabase
        .from("reporting_integration_connections")
        .select("id,provider")
        .eq("company_id", state.companyId)
        .in("provider", [...googleProviders]);

      if (connectionsError) {
        throw new Error(connectionsError.message);
      }

      for (const connection of connections ?? []) {
        const connectionProvider =
          parseProvider(connection.provider);

        if (!connectionProvider) continue;

        await credentialStore.write(
          connection.id,
          connectionProvider,
          credential,
        );
      }

      const ids = (connections ?? [])
        .map((connection) => connection.id);

      if (ids.length) {
        const { error } = await access.supabase
          .from("reporting_integration_connections")
          .update({
            status: "connected",
            error_message: null,
            updated_at: new Date().toISOString(),
          })
          .in("id", ids);

        if (error) throw new Error(error.message);
      }
    } else {
      await credentialStore.write(
        access.connection.id,
        provider,
        credential,
      );

      const metaReadiness = provider === "meta"
        ? parseMetaPermissionRows(Object.entries(credential.permissionStatuses ?? {}).map(
            ([permission, status]) => ({ permission, status }),
          ))
        : null;

      const { error } = await access.supabase
        .from("reporting_integration_connections")
        .update({
          status: "connected",
          error_message: null,
          ...(metaReadiness ? {
            configuration: {
              ...(access.connection.configuration ?? {}),
              meta_permission_status: metaReadiness.status,
              meta_granted_permissions: metaReadiness.granted,
              meta_missing_permissions: metaReadiness.missing,
            },
          } : {}),
          updated_at: new Date().toISOString(),
        })
        .eq("id", access.connection.id);

      if (error) throw new Error(error.message);
    }

    return NextResponse.redirect(
      new URL(
        `/integrations?integration_connected=${encodeURIComponent(provider)}`,
        url.origin,
      ),
    );
  } catch (error) {
    let message =
      error instanceof Error
        ? error.message
        : "Invalid OAuth callback.";

    if (resetConnection) {
      try {
        await resetConnection(message);
      } catch (resetError) {
        const resetMessage =
          resetError instanceof Error
            ? resetError.message
            : "Unable to reset the integration state.";
        message = `${message} ${resetMessage}`;
      }
    }

    return NextResponse.redirect(
      new URL(
        `/integrations?integration_error=${encodeURIComponent(message)}`,
        url.origin,
      ),
    );
  }
}

import { NextResponse } from "next/server";
import { requireIntegrationConnection } from "@/lib/integrations/access";
import { parseProvider } from "@/lib/integrations/catalog";
import { credentialStore } from "@/lib/integrations/credentials";
import { getGoogleCredential, isGoogleProvider } from "@/lib/integrations/google/client";
import { findAccessibleResource } from "@/lib/integrations/google/core";
import { discoverGoogleResources, googleResourceConfiguration } from "@/lib/integrations/google/resources";
import { discoverMetaAdAccounts } from "@/lib/integrations/meta/client";
import { normalizeMetaAdAccountId } from "@/lib/integrations/meta/core";

export const runtime = "nodejs";

const safeKeys = new Set(["account_id","account_name","ad_account_id","ad_account_name","customer_id","customer_name","login_customer_id","currency","timezone","property_id","property_name","site_url","location_id","location_name","board_id","board_name","portal_id","portal_name","pipeline_id","pipeline_name","endpoint_name","monday_columns"]);

export async function PATCH(request: Request, { params }: { params: Promise<{ provider: string }> }) {
  const provider = parseProvider((await params).provider);
  if (!provider) return NextResponse.json({ error: "Unknown integration provider." }, { status: 404 });
  const body = await request.json().catch(() => ({})) as { companyId?: string; configuration?: Record<string, unknown> };
  if (!body.companyId || !body.configuration) return NextResponse.json({ error: "companyId and configuration are required." }, { status: 400 });
  const invalid = Object.keys(body.configuration).filter((key) => !safeKeys.has(key));
  if (invalid.length) return NextResponse.json({ error: `Secret or unsupported configuration fields are not accepted: ${invalid.join(", ")}.` }, { status: 400 });
  if (!isSafeConfiguration(body.configuration)) return NextResponse.json({ error: "Configuration values must contain only resource identifiers, display names, URLs, or Monday column IDs." }, { status: 400 });
  const access = await requireIntegrationConnection(body.companyId, provider);
  if ("error" in access) return NextResponse.json({ error: access.error }, { status: access.status });
  let requestedConfiguration = body.configuration;

  if (provider === "meta") {
    const requestedId = typeof body.configuration.ad_account_id === "string"
      ? normalizeMetaAdAccountId(body.configuration.ad_account_id)
      : "";
    if (!requestedId) return NextResponse.json({ error: "Select a Meta ad account." }, { status: 400 });

    try {
      const credential = await credentialStore.read(access.connection.id, provider);
      if (!credential?.accessToken) return NextResponse.json({ error: "Reconnect Meta before selecting an ad account." }, { status: 409 });
      const accounts = await discoverMetaAdAccounts(credential.accessToken);
      const selected = accounts.find(account => account.id === requestedId);
      if (!selected) return NextResponse.json({ error: "That ad account is not accessible to the authorized Meta user." }, { status: 403 });
      requestedConfiguration = {
        ad_account_id: selected.id,
        ad_account_name: selected.name,
      };
    } catch (error) {
      return NextResponse.json({ error: error instanceof Error ? error.message : "Unable to validate the Meta ad account." }, { status: 502 });
    }
  } else if (isGoogleProvider(provider)) {
    const requestedId = googleRequestedResourceId(provider, body.configuration);
    if (!requestedId) return NextResponse.json({ error: "Select a Google resource." }, { status: 400 });

    try {
      const credential = await getGoogleCredential(access.connection.id, provider);
      const resources = await discoverGoogleResources(provider, credential.accessToken);
      const selected = findAccessibleResource(resources, requestedId);
      if (!selected) return NextResponse.json({ error: "That resource is not accessible to the authorized Google user." }, { status: 403 });
      requestedConfiguration = googleResourceConfiguration(provider, selected);
    } catch (error) {
      return NextResponse.json({ error: error instanceof Error ? error.message : "Unable to validate the Google resource." }, { status: 502 });
    }
  }

  const configuration = isGoogleProvider(provider)
    ? requestedConfiguration
    : { ...(access.connection.configuration as Record<string, unknown>), ...requestedConfiguration };
  const { error } = await access.supabase.from("reporting_integration_connections").update({ configuration, updated_at: new Date().toISOString() }).eq("id", access.connection.id).select("id").single();
  if (error) return NextResponse.json({ error: error.message }, { status: 500 });
  return NextResponse.json({ message: "Resource selection saved.", configuration });
}

function googleRequestedResourceId(
  provider: "google_ads" | "ga4" | "search_console" | "google_business",
  configuration: Record<string, unknown>,
) {
  const key = {
    google_ads: "customer_id",
    ga4: "property_id",
    search_console: "site_url",
    google_business: "location_id",
  }[provider];
  const value = configuration[key];
  return typeof value === "string" ? value.trim() : "";
}

function isSafeConfiguration(configuration: Record<string, unknown>) {
  return Object.entries(configuration).every(([key, value]) => {
    if (key === "monday_columns") return Boolean(value) && typeof value === "object" && !Array.isArray(value) && Object.values(value as Record<string, unknown>).every((column) => typeof column === "string" && column.length <= 200);
    return typeof value === "string" && value.length <= 2000;
  });
}

import { NextResponse } from "next/server";
import { requireIntegrationConnection } from "@/lib/integrations/access";
import { parseProvider } from "@/lib/integrations/catalog";

export async function POST(request: Request, { params }: { params: Promise<{ provider: string }> }) {
  const provider = parseProvider((await params).provider);
  if (!provider) return NextResponse.json({ error: "Unknown integration provider." }, { status: 404 });
  const body = await request.json().catch(() => ({})) as { companyId?: string };
  if (!body.companyId) return NextResponse.json({ error: "companyId is required." }, { status: 400 });
  const access = await requireIntegrationConnection(body.companyId, provider);
  if ("error" in access) return NextResponse.json({ error: access.error }, { status: access.status });
  if (access.connection.status !== "connected") return NextResponse.json({ error: "This integration is already disconnected." }, { status: 409 });
  return NextResponse.json({ error: "Disconnect is prepared but disabled until token revocation and secure deletion are implemented together." }, { status: 503 });
}

import { NextResponse } from "next/server";

import { requireIntegrationConnection } from "@/lib/integrations/access";
import { parseProvider } from "@/lib/integrations/catalog";
import { credentialStore } from "@/lib/integrations/credentials";
import { getGoogleCredential, isGoogleProvider } from "@/lib/integrations/google/client";
import { discoverGoogleResources } from "@/lib/integrations/google/resources";
import { discoverMetaAdAccounts } from "@/lib/integrations/meta/client";

export const runtime = "nodejs";

export async function GET(
  request: Request,
  { params }: { params: Promise<{ provider: string }> },
) {
  const provider = parseProvider((await params).provider);
  if (!provider) return json({ error: "Unknown integration provider." }, 404);

  const companyId = new URL(request.url).searchParams.get("companyId") ?? "";
  if (!companyId) return json({ error: "companyId is required." }, 400);

  const access = await requireIntegrationConnection(companyId, provider);
  if ("error" in access) return json({ error: access.error }, access.status);

  try {
    if (provider === "meta") {
      const credential = await credentialStore.read(access.connection.id, provider);
      if (!credential?.accessToken) return json({ error: "Reconnect Meta before loading ad accounts." }, 409);
      const resources = await discoverMetaAdAccounts(credential.accessToken);
      return json({ resources });
    }

    if (isGoogleProvider(provider)) {
      const credential = await getGoogleCredential(access.connection.id, provider);
      const resources = await discoverGoogleResources(provider, credential.accessToken);
      return json({ resources });
    }

    return json({ error: "Resource discovery is not implemented for this provider." }, 501);
  } catch (error) {
    return json({ error: error instanceof Error ? error.message : "Unable to load provider resources." }, 502);
  }
}

function json(body: Record<string, unknown>, status = 200) {
  return NextResponse.json(body, {
    status,
    headers: { "Cache-Control": "private, no-store" },
  });
}

import { NextResponse } from "next/server";
import { requireIntegrationConnection } from "@/lib/integrations/access";
import { parseProvider } from "@/lib/integrations/catalog";
import { credentialStore } from "@/lib/integrations/credentials";
import { generateWebsiteFormsSecret } from "@/lib/integrations/website-forms";

export const runtime = "nodejs";

export async function GET(
  request: Request,
  { params }: { params: Promise<{ provider: string }> },
) {
  const access = await requireWebsiteFormsAccess(request, params);

  if ("response" in access) return access.response;

  try {
    const credential = await credentialStore.read(
      access.connection.id,
      "website_forms",
    );

    return noStoreJson({ secretPresent: Boolean(credential?.accessToken) });
  } catch (error) {
    return noStoreJson(
      {
        error: error instanceof Error
          ? error.message
          : "Unable to check the Website Forms signing secret.",
      },
      500,
    );
  }
}

export async function POST(
  request: Request,
  { params }: { params: Promise<{ provider: string }> },
) {
  const access = await requireWebsiteFormsAccess(request, params);

  if ("response" in access) return access.response;

  let body: { action?: unknown };
  try {
    body = await request.json() as { action?: unknown };
  } catch {
    return noStoreJson({ error: "Request body must be valid JSON." }, 400);
  }

  if (body.action !== "rotate") {
    return noStoreJson(
      { error: "Only action=rotate is supported. Existing secrets cannot be revealed." },
      400,
    );
  }

  try {
    const secret = generateWebsiteFormsSecret();
    await credentialStore.write(
      access.connection.id,
      "website_forms",
      { accessToken: secret, scopes: [] },
    );

    return noStoreJson({
      secret,
      message:
        "Copy this signing secret now. It will not be shown again.",
    });
  } catch (error) {
    return noStoreJson(
      {
        error: error instanceof Error
          ? error.message
          : "Unable to rotate the Website Forms signing secret.",
      },
      500,
    );
  }
}

async function requireWebsiteFormsAccess(
  request: Request,
  params: Promise<{ provider: string }>,
) {
  const provider = parseProvider((await params).provider);

  if (provider !== "website_forms") {
    return {
      response: noStoreJson(
        { error: "Signing-secret management is only available for Website Forms." },
        404,
      ),
    };
  }

  const companyId = new URL(request.url).searchParams.get("companyId") ?? "";
  if (!companyId) {
    return {
      response: noStoreJson({ error: "companyId is required." }, 400),
    };
  }

  const access = await requireIntegrationConnection(companyId, provider);
  if ("error" in access) {
    return {
      response: noStoreJson({ error: access.error }, access.status),
    };
  }

  return access;
}

function noStoreJson(body: unknown, status = 200) {
  return NextResponse.json(body, {
    status,
    headers: { "Cache-Control": "no-store" },
  });
}

import { NextResponse } from "next/server";

import { requireIntegrationConnection } from "@/lib/integrations/access";
import { parseProvider, providerCatalog } from "@/lib/integrations/catalog";
import { syncCrmProvider } from "@/lib/integrations/crm-sync";
import { isGoogleProvider } from "@/lib/integrations/google/client";
import { syncGoogleProvider, type GoogleSyncResult } from "@/lib/integrations/google-sync";
import { syncMetaProvider } from "@/lib/integrations/meta-sync";
import { syncRobawsProvider } from "@/lib/integrations/robaws-sync";
import type { ConnectionConfiguration, IntegrationProvider } from "@/lib/integrations/types";
import { createSupabaseAdminClient } from "@/lib/supabase/admin";

export const runtime = "nodejs";

type AdminClient = ReturnType<typeof createSupabaseAdminClient>;
type StandardSyncResult = {
  recordsImported: number;
  clientsImported?: number;
  clientsMatched?: number;
  clientsUnmatched?: number;
  leadsImported: number;
  leadsMatched?: number;
  dealsImported: number;
  quotesImported?: number;
  projectsImported: number;
  invoicesImported?: number;
  revenueImported: number;
};

type MetaSyncResult = Awaited<ReturnType<typeof syncMetaProvider>>;
type SyncResult = StandardSyncResult | MetaSyncResult | GoogleSyncResult;

export async function POST(
  request: Request,
  { params }: { params: Promise<{ provider: string }> },
) {
  const provider = parseProvider((await params).provider);

  if (!provider) {
    return json({ error: "Unknown integration provider." }, 404);
  }

  const body = await request.json().catch(() => ({})) as { companyId?: string };

  if (!body.companyId) {
    return json({ error: "companyId is required." }, 400);
  }

  const access = await requireIntegrationConnection(body.companyId, provider);

  if ("error" in access) {
    return json({ error: access.error }, access.status);
  }

  if (access.connection.status !== "connected") {
    return json(
      { error: `${providerCatalog[provider].name} is not connected.` },
      409,
    );
  }

  if (!isManualSyncProvider(provider)) {
    return json(
      { error: `${providerCatalog[provider].name} data sync is not implemented yet.` },
      503,
    );
  }

  let admin: AdminClient;

  try {
    admin = createSupabaseAdminClient();
  } catch (error) {
    return json({ error: errorMessage(error, "Server-side sync access is not configured.") }, 500);
  }

  const startedAt = new Date().toISOString();
  const configuredAdAccountId = provider === "meta" &&
    typeof access.connection.configuration?.ad_account_id === "string"
    ? access.connection.configuration.ad_account_id
    : null;
  const logResult = await admin
    .from("sync_logs")
    .insert({
      integration_connection_id: access.connection.id,
      started_at: startedAt,
      status: "running",
      records_imported: 0,
      metadata: provider === "meta"
        ? {
            trigger: "manual",
            provider,
            companyId: body.companyId,
            adAccountId: configuredAdAccountId,
          }
        : { trigger: "manual", provider },
    })
    .select("id")
    .single();

  if (logResult.error) {
    return json(
      { error: `Unable to start the sync log: ${logResult.error.message}` },
      500,
    );
  }

  const attemptResult = await admin
    .from("reporting_integration_connections")
    .update({
      last_attempted_sync: startedAt,
      error_message: null,
      updated_at: startedAt,
    })
    .eq("id", access.connection.id)
    .select("id")
    .single();

  if (attemptResult.error) {
    const message = `Unable to save the sync attempt: ${attemptResult.error.message}`;
    const loggingErrors = await persistFailure(
      admin,
      access.connection.id,
      logResult.data.id,
      startedAt,
      message,
    );
    return json({ error: appendPersistenceErrors(message, loggingErrors) }, 500);
  }

  let result: SyncResult;

  try {
    result = provider === "robaws"
      ? await syncRobawsProvider(body.companyId)
      : provider === "meta"
        ? await syncMetaProvider(
            access.connection.id,
            body.companyId,
            access.connection.configuration as ConnectionConfiguration,
          )
        : isGoogleProvider(provider)
          ? await syncGoogleProvider(
              provider,
              access.connection.id,
              body.companyId,
              access.connection.configuration as ConnectionConfiguration,
            )
        : await syncCrmProvider(
          provider,
          body.companyId,
          access.connection.configuration as Record<string, unknown>,
        );
  } catch (error) {
    const message = errorMessage(error, `${providerCatalog[provider].name} sync failed.`);
    const loggingErrors = await persistFailure(
      admin,
      access.connection.id,
      logResult.data.id,
      startedAt,
      message,
    );
    return json({ error: appendPersistenceErrors(message, loggingErrors) }, 502);
  }

  const completedAt = new Date().toISOString();
  const metadata = provider === "meta"
    ? metaSyncMetadata(
        result as MetaSyncResult,
        body.companyId,
        configuredAdAccountId,
      )
    : isGoogleProvider(provider)
      ? googleSyncMetadata(result as GoogleSyncResult, body.companyId)
    : standardSyncMetadata(
        provider,
        result as StandardSyncResult,
      );

  const logSuccess = await admin
    .from("sync_logs")
    .update({
      completed_at: completedAt,
      status: "success",
      records_imported: result.recordsImported,
      error_message: null,
      metadata,
    })
    .eq("id", logResult.data.id)
    .select("id")
    .single();

  if (logSuccess.error) {
    return json(
      { error: `The provider sync completed, but its success log could not be saved: ${logSuccess.error.message}` },
      500,
    );
  }

  const connectionSuccess = await admin
    .from("reporting_integration_connections")
    .update({
      status: "connected",
      last_successful_sync: completedAt,
      last_attempted_sync: startedAt,
      error_message: null,
      ...(provider === "meta" ? {
        configuration: {
          ...(access.connection.configuration ?? {}),
          meta_permission_status: (result as MetaSyncResult).metaPermissionStatus,
          meta_granted_permissions: (result as MetaSyncResult).grantedPermissions,
          meta_missing_permissions: (result as MetaSyncResult).missingPermissions,
        },
      } : {}),
      updated_at: completedAt,
    })
    .eq("id", access.connection.id)
    .select("id")
    .single();

  if (connectionSuccess.error) {
    return json(
      { error: `The provider sync completed, but the integration state could not be updated: ${connectionSuccess.error.message}` },
      500,
    );
  }

  return json({
    message: successMessage(provider, result),
    provider,
    startedAt,
    completedAt,
    ...result,
  });
}

function isManualSyncProvider(provider: IntegrationProvider): provider is "meta" | "google_ads" | "ga4" | "search_console" | "google_business" | "monday" | "hubspot" | "robaws" {
  return provider === "meta" || isGoogleProvider(provider) || provider === "monday" || provider === "hubspot" || provider === "robaws";
}

function successMessage(provider: "meta" | "google_ads" | "ga4" | "search_console" | "google_business" | "monday" | "hubspot" | "robaws", result: SyncResult) {
  if (provider === "meta") {
    const meta = result as MetaSyncResult;
    if (!meta.leadAdsAvailable) {
      return `Meta Ads synced successfully: ${meta.dailyRowsImported} daily ad rows, but Lead Ads retrieval is unavailable because these permissions are missing: ${meta.missingPermissions.join(", ")}.`;
    }
    const leadSummary = meta.metaLeadAttributionWarning
      ? `Lead Ads warning: ${meta.metaLeadAttributionWarning}`
      : `${meta.metaLeadsImported} Meta leads · ${meta.metaLeadsMatched} CRM matches`;
    return `Meta Ads synced successfully: ${meta.dailyRowsImported} daily ad rows · ${meta.campaignsImported} campaigns · ${meta.adsetsImported} ad sets · ${meta.adsImported} ads · ${leadSummary}.`;
  }

  if (isGoogleProvider(provider)) {
    const google = result as GoogleSyncResult;
    if (provider === "google_ads") {
      return `Google Ads synced: ${google.dailyRowsImported} daily rows · ${google.campaignsImported ?? 0} campaigns · €${(google.totalSpend ?? 0).toFixed(2)} spend.`;
    }
    if (provider === "ga4") return `GA4 synced: ${google.dailyRowsImported} daily rows.`;
    if (provider === "search_console") return `Search Console synced: ${google.recordsImported} search rows.`;
    return `Google Business Profile synced: ${google.dailyRowsImported} daily rows.`;
  }

  const standard = result as StandardSyncResult;

  if (provider === "robaws") {
    return `ROBAWS synced successfully: ${standard.clientsImported ?? 0} clients (${standard.clientsMatched ?? 0} matched, ${standard.clientsUnmatched ?? 0} unmatched) · ${standard.leadsMatched ?? standard.leadsImported} matched CRM leads · ${standard.quotesImported ?? 0} offers · ${standard.projectsImported} projects · ${standard.invoicesImported ?? 0} invoices.`;
  }

  return `${providerCatalog[provider].name} synced successfully: ${standard.leadsImported} leads · ${standard.dealsImported} deals · ${standard.projectsImported} projects · ${standard.revenueImported} revenue records.`;
}

function googleSyncMetadata(result: GoogleSyncResult, companyId: string) {
  return {
    trigger: "manual",
    provider: result.provider,
    companyId,
    recordsImported: result.recordsImported,
    dailyRowsImported: result.dailyRowsImported,
    campaignsImported: result.campaignsImported,
    adGroupsImported: result.adGroupsImported,
    adsImported: result.adsImported,
    spendImported: result.totalSpend,
    dateFrom: result.dateFrom,
    dateTo: result.dateTo,
    selectedResourceId: result.selectedResourceId,
  };
}

function metaSyncMetadata(
  result: MetaSyncResult,
  companyId: string,
  configuredAdAccountId: string | null,
) {
  return {
    trigger: "manual",
    provider: "meta",
    dailyRowsImported: result.dailyRowsImported,
    campaignsImported: result.campaignsImported,
    adsetsImported: result.adsetsImported,
    adsImported: result.adsImported,
    dateFrom: result.dateFrom,
    dateTo: result.dateTo,
    earliestDate: result.earliestDate,
    latestDate: result.latestDate,
    totalSpend: result.totalSpend,
    selectedAdAccountId: result.selectedAdAccountId,
    monthlySpend: result.monthlySpend,
    missingMonths: result.missingMonths,
    companyId,
    adAccountId:
      result.selectedAdAccountId ?? configuredAdAccountId,
    spendImported: result.totalSpend,
    firstDate: result.earliestDate,
    lastDate: result.latestDate,
    metaLeadsImported: result.metaLeadsImported,
    metaLeadsMatched: result.metaLeadsMatched,
    metaLeadsUnmatched: result.metaLeadsUnmatched,
    metaLeadsAmbiguous: result.metaLeadsAmbiguous,
    earliestMetaLead: result.earliestMetaLead,
    latestMetaLead: result.latestMetaLead,
    metaLeadMatchRate: result.metaLeadMatchRate,
    metaLeadAttributionWarning: result.metaLeadAttributionWarning,
    metaPermissionStatus: result.metaPermissionStatus,
    grantedPermissions: result.grantedPermissions,
    missingPermissions: result.missingPermissions,
    leadAdsAvailable: result.leadAdsAvailable,
    metaLeadRetrievalScope: result.metaLeadRetrievalScope,
    metaLeadPagesProcessed: result.metaLeadPagesProcessed,
    metaLeadFormsProcessed: result.metaLeadFormsProcessed,
  };
}

function standardSyncMetadata(
  provider: "monday" | "hubspot" | "robaws",
  result: StandardSyncResult,
) {
  return {
    trigger: "manual",
    provider,
    clientsImported: result.clientsImported ?? 0,
    clientsMatched: result.clientsMatched ?? 0,
    clientsUnmatched: result.clientsUnmatched ?? 0,
    leadsImported: result.leadsImported,
    leadsMatched:
      result.leadsMatched ?? result.leadsImported,
    dealsImported: result.dealsImported,
    quotesImported: result.quotesImported ?? 0,
    projectsImported: result.projectsImported,
    invoicesImported: result.invoicesImported ?? 0,
    revenueImported: result.revenueImported,
  };
}

async function persistFailure(
  admin: AdminClient,
  connectionId: string,
  logId: number | string,
  startedAt: string,
  message: string,
) {
  const completedAt = new Date().toISOString();
  const [connectionResult, logResult] = await Promise.all([
    admin
      .from("reporting_integration_connections")
      .update({
        status: "error",
        last_attempted_sync: startedAt,
        error_message: message,
        updated_at: completedAt,
      })
      .eq("id", connectionId)
      .select("id")
      .single(),
    admin
      .from("sync_logs")
      .update({
        completed_at: completedAt,
        status: "error",
        error_message: message,
      })
      .eq("id", logId)
      .select("id")
      .single(),
  ]);

  return [
    connectionResult.error
      ? `integration state: ${connectionResult.error.message}`
      : null,
    logResult.error
      ? `sync log: ${logResult.error.message}`
      : null,
  ].filter((value): value is string => Boolean(value));
}

function appendPersistenceErrors(message: string, errors: string[]) {
  return errors.length
    ? `${message} Additionally unable to persist ${errors.join("; ")}.`
    : message;
}

function errorMessage(error: unknown, fallback: string) {
  return error instanceof Error && error.message ? error.message : fallback;
}

function json(body: Record<string, unknown>, status = 200) {
  return NextResponse.json(body, {
    status,
    headers: { "Cache-Control": "private, no-store" },
  });
}

import { NextResponse } from "next/server";
import { credentialStore } from "@/lib/integrations/credentials";
import { verifyWebsiteFormsSignature } from "@/lib/integrations/website-forms";
import { createSupabaseAdminClient } from "@/lib/supabase/admin";

export const runtime = "nodejs";

type LeadPayload = {
  company?: string;
  created_at?: string;
  name?: string;
  email?: string;
  phone?: string;
  service?: string;
  municipality?: string;
  postal_code?: string;
  landing_page?: string;
  referrer?: string;
  source?: string;
  utm_source?: string;
  utm_medium?: string;
  utm_campaign?: string;
  utm_content?: string;
  utm_term?: string;
  gclid?: string;
  fbclid?: string;
  meta_lead_id?: string;
  form_name?: string;
  form_type?: string;
  notes?: string;
};

export async function POST(request: Request) {
  const rawBody = await request.text();
  let payload: LeadPayload;
  try { payload = JSON.parse(rawBody) as LeadPayload; }
  catch { return NextResponse.json({ error: "Request body must be valid JSON." }, { status: 400 }); }

  const companySlug = clean(payload.company, 100);
  const idempotencyKey = clean(request.headers.get("x-idempotency-key"), 200);
  if (!companySlug || !idempotencyKey) return NextResponse.json({ error: "company and x-idempotency-key are required." }, { status: 400 });

  try {
    const supabase = createSupabaseAdminClient();
    const { data: company, error: companyError } = await supabase.from("companies").select("id").eq("slug", companySlug).eq("is_active", true).maybeSingle();
    if (companyError) throw companyError;
    if (!company) return NextResponse.json({ error: "Unknown company." }, { status: 404 });

    const { data: connection, error: connectionError } = await supabase
      .from("reporting_integration_connections")
      .select("id,status")
      .eq("company_id", company.id)
      .eq("provider", "website_forms")
      .maybeSingle();
    if (connectionError) throw connectionError;
    if (!connection || connection.status !== "connected") {
      return NextResponse.json(
        { error: "Lead ingestion is not configured for this company." },
        { status: 503 },
      );
    }

    const credential = await credentialStore.read(
      connection.id,
      "website_forms",
    );
    const signature = await verifyWebsiteFormsSignature({
      body: rawBody,
      headers: request.headers,
      secret: credential?.accessToken,
    });
    if (!signature.ok) {
      return NextResponse.json(
        { error: signature.error },
        { status: signature.status },
      );
    }

    const name = clean(payload.name, 200);
    if (!name || (!payload.email && !payload.phone)) return NextResponse.json({ error: "name and either email or phone are required." }, { status: 400 });

    let serviceId: string | null = null;
    const serviceName = clean(payload.service, 200);
    if (serviceName) {
      const { data: service } = await supabase.from("services").select("id").eq("company_id", company.id).ilike("name", serviceName).maybeSingle();
      serviceId = service?.id ?? null;
    }

    const row = {
      company_id: company.id,
      ingestion_key: idempotencyKey,
      created_at: validDate(payload.created_at) ?? new Date().toISOString(),
      name,
      email: clean(payload.email, 320),
      phone: clean(payload.phone, 80),
      service_id: serviceId,
      municipality: clean(payload.municipality, 160),
      postal_code: clean(payload.postal_code, 40),
      landing_page: clean(payload.landing_page, 2000),
      referrer: clean(payload.referrer, 2000),
      source: clean(payload.source, 160) ?? "website",
      utm_source: clean(payload.utm_source, 500), utm_medium: clean(payload.utm_medium, 500), utm_campaign: clean(payload.utm_campaign, 500), utm_content: clean(payload.utm_content, 500), utm_term: clean(payload.utm_term, 500),
      gclid: clean(payload.gclid, 500), fbclid: clean(payload.fbclid, 500), meta_lead_id: clean(payload.meta_lead_id, 500),
      form_name: clean(payload.form_name, 200), form_type: clean(payload.form_type, 100), notes: clean(payload.notes, 5000),
    };
    const { data: lead, error } = await supabase.from("leads").upsert(row, { onConflict: "company_id,ingestion_key" }).select("id").single();
    if (error) throw error;
    return NextResponse.json({ accepted: true, leadId: lead.id }, { status: 202 });
  } catch (error) {
    const message = error instanceof Error ? error.message : "Lead ingestion failed.";
    return NextResponse.json({ error: message }, { status: message.includes("SUPABASE_SECRET_KEY") ? 503 : 500 });
  }
}

function clean(value: unknown, maxLength: number) { return typeof value === "string" && value.trim() ? value.trim().slice(0, maxLength) : null; }
function validDate(value: unknown) { if (typeof value !== "string") return null; const date = new Date(value); return Number.isNaN(date.getTime()) ? null : date.toISOString(); }

import { createSupabaseServerClient } from "@/lib/supabase/server";
import { NextResponse } from "next/server";

export async function GET(request: Request) {
  const url = new URL(request.url);
  const code = url.searchParams.get("code");
  const requestedNext = url.searchParams.get("next");
  const next = requestedNext?.startsWith("/") && !requestedNext.startsWith("//") ? requestedNext : "/overview";

  if (code) {
    const supabase = await createSupabaseServerClient();
    const { error } = await supabase.auth.exchangeCodeForSession(code);
    if (!error) return NextResponse.redirect(new URL(next, url.origin));
  }

  return NextResponse.redirect(new URL("/sign-in?error=This%20link%20is%20invalid%20or%20has%20expired.", url.origin));
}

"use client";

import Link from "next/link";
import { FormEvent, useState } from "react";
import { createSupabaseBrowserClient } from "@/lib/supabase/client";

export default function ForgotPasswordPage() {
  const [email, setEmail] = useState("");
  const [error, setError] = useState("");
  const [sent, setSent] = useState(false);
  const [submitting, setSubmitting] = useState(false);

  async function requestReset(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setError("");
    setSubmitting(true);

    const supabase = createSupabaseBrowserClient();
    const { error: resetError } = await supabase.auth.resetPasswordForEmail(email.trim(), {
      redirectTo: `${window.location.origin}/auth/callback?next=/reset-password`,
    });

    setSubmitting(false);
    if (resetError) {
      setError(resetError.message);
      return;
    }
    setSent(true);
  }

  return (
    <main className="grid min-h-screen place-items-center bg-[#181a1d] p-6">
      <div className="w-full max-w-sm bg-white p-7">
        <p className="text-xs font-bold uppercase tracking-[.18em] text-[#70736d]">WAT Agency</p>
        <h1 className="mt-3 text-2xl font-semibold tracking-tight">Reset your password</h1>
        <p className="mt-2 text-sm leading-6 text-[#6c706b]">We’ll email you a secure link to choose a new password.</p>

        {sent ? (
          <div className="mt-6">
            <p className="bg-lime-50 p-4 text-sm leading-6 text-[#344500]">Check your inbox. If an account exists for this email, a password reset link is on its way.</p>
            <Link href="/sign-in" className="mt-5 inline-flex text-sm font-semibold text-[#4f5f16] underline decoration-[#a3bf4c] underline-offset-4 hover:text-[#182000]">Back to sign in</Link>
          </div>
        ) : (
          <form onSubmit={requestReset} className="mt-6 space-y-4">
            {error && <p className="bg-rose-50 p-3 text-sm text-rose-800">{error}</p>}
            <label className="block text-sm font-semibold">Email
              <input value={email} onChange={(event) => setEmail(event.target.value)} name="email" type="email" required autoComplete="email" className="mt-2 h-11 w-full border border-[#d5d6d0] px-3 font-normal outline-none focus:border-[#181a1d]" />
            </label>
            <button disabled={submitting} className="h-11 w-full bg-[#c9fa3c] text-sm font-bold text-[#182000]">{submitting ? "Sending…" : "Send reset link"}</button>
            <Link href="/sign-in" className="block text-center text-sm font-semibold text-[#4f5f16] underline decoration-[#a3bf4c] underline-offset-4 hover:text-[#182000]">Back to sign in</Link>
          </form>
        )}
      </div>
    </main>
  );
}

