export function SalesTeamPage({ data }: { data: CompanyDataset }) {
  const rows=buildJourneyRows(data),names=[...new Set(rows.map(r=>r.lead.salesperson||"Unassigned"))];
  const team=names.map(name=>{const g=rows.filter(r=>(r.lead.salesperson||"Unassigned")===name);return {name,leads:g.length,visits:g.filter(r=>r.hasVisit).length,offersCreated:g.filter(r=>r.offers.length>0).length,offers:g.filter(r=>r.offers.some(o=>Boolean(o.sentAt))).length,quoted:g.reduce((n,r)=>n+r.sentOfferValue,0),open:g.reduce((n,r)=>n+r.openOfferValue,0),signed:g.filter(r=>r.isSigned).length,verified:g.filter(r=>r.stage==="verified").length,revenue:g.reduce((n,r)=>n+r.projectValue,0)}}).sort((a,b)=>b.revenue-a.revenue||b.leads-a.leads);
  return <Card className="p-5"><SectionHeader title="Sales team performance" description="Separates lead quality from sales execution; unassigned leads remain visible."/><div className="table-scroll"><table><thead><tr><th>Salesperson</th><th>Unique people</th><th>Visits</th><th>Offers created</th><th>Sent</th><th>Sent €</th><th>Open sent €</th><th>CRM signed</th><th>Verified</th><th>Revenue</th><th>Offer → verified</th></tr></thead><tbody>{team.map(r=><tr key={r.name}><td className="font-semibold">{r.name}</td><td>{r.leads}</td><td>{r.visits}</td><td>{r.offersCreated}</td><td>{r.offers}</td><td>{formatCurrency(r.quoted)}</td><td>{formatCurrency(r.open)}</td><td>{r.signed}</td><td>{r.verified}</td><td>{formatCurrency(r.revenue)}</td><td>{formatPercent(percentage(r.verified,r.offers))}</td></tr>)}</tbody></table></div></Card>;
}

function Funnel({ data }: { data: CompanyDataset }) {
  const s=buildFunnelSummary(data);
  const stages=[["Leads",s.leads],["Unique",s.uniquePeople],["Qualified",s.qualified],["Visits",s.visits],["Offers created",s.offersCreated],["Sent",s.offersSent],["Open",s.openOffers],["Accepted",s.acceptedOffers],["Signed",s.crmSigned],["Commercial clients",s.commercialClients]] as const;
  return <Card className="overflow-hidden"><div className="overflow-x-auto"><div className="flex min-w-[1320px] divide-x divide-[var(--line)]"><div className="min-w-[150px] bg-[var(--ink)] p-4 text-white"><span className="text-xs uppercase text-white/60">Spend</span><strong className="mt-2 block text-xl">{formatCurrency(data.metrics.spend,true)}</strong></div>{stages.map(([label,value])=><div key={label} className="min-w-[130px] flex-1 bg-white p-4"><span className="text-xs uppercase text-[var(--muted)]">{label}</span><strong className="mt-2 block text-xl">{value}</strong></div>)}</div></div></Card>;
}

function JourneyCard({ row,onOpen }: { row: JourneyRow; onOpen:()=>void }) { const a=[...row.appointments].sort((x,y)=>y.scheduledAt.localeCompare(x.scheduledAt))[0],o=row.latestOffer; return <button onClick={onOpen} className="w-full border border-[var(--line)] bg-white p-3 text-left transition hover:border-[var(--ink)]"><div className="flex justify-between gap-2"><strong className="text-sm">{row.lead.name}</strong><StatusPill tone={tone(row.stage)}>{journeyStageMeta.find(s=>s.key===row.stage)?.label}</StatusPill></div><p className="mt-1 text-[11px] text-[var(--muted)]">{row.lead.source+" · "+row.lead.service}</p>{row.crmRecordCount>1&&<p className="mt-1 text-[11px] font-semibold text-amber-700">{row.crmRecordCount+" CRM records merged"}</p>}<div className="mt-3 space-y-1 text-xs"><p>Lead: {date(row.lead.date)}</p>{a&&<p>Visit: {dateTime(a.completedAt??a.scheduledAt)}</p>}{o&&<p>Offer: <b>{formatCurrency(o.priceInclVat)}</b> · {o.sentAt?"sent "+dateTime(o.sentAt):"send not verified"}</p>}{row.projectValue>0&&<p>Project: <b>{formatCurrency(row.projectValue)}</b></p>}</div></button>; }
function ClientDrawer({row,onClose}:{row:JourneyRow;onClose:()=>void}) {
  return <div className="fixed inset-0 z-50 bg-black/35 p-4" onMouseDown={onClose}><aside className="ml-auto h-full w-full max-w-xl overflow-y-auto bg-white shadow-2xl" onMouseDown={e=>e.stopPropagation()}>
    <header className="sticky top-0 z-10 flex items-start justify-between border-b border-[var(--line)] bg-white p-5"><div><p className="eyebrow">Client evidence</p><h2 className="mt-1 text-xl font-semibold">{row.lead.name}</h2><p className="mt-1 text-sm text-[var(--muted)]">{row.lead.source+" · "+row.lead.service+" · "+row.lead.municipality}</p></div><button onClick={onClose} className="p-2" aria-label="Close client details"><X size={18}/></button></header>
    <div className="space-y-6 p-5">
      <div className="grid gap-px bg-[var(--line)] sm:grid-cols-2"><Mini label="CRM records merged" value={String(row.crmRecordCount)}/><Mini label="First-touch source" value={row.lead.source}/><Mini label="Sources seen" value={row.sourcesSeen.join(" → ")}/><Mini label="Salesperson" value={row.lead.salesperson}/></div>
      <section><h3 className="mb-3 text-sm font-semibold">Client</h3><div className="space-y-2 text-sm"><p><b>Email:</b> {row.lead.email||"—"}</p><p><b>Phone:</b> {row.lead.phone||"—"}</p><p><b>Campaign:</b> {row.lead.campaign}</p><p><b>CRM status:</b> {row.lead.crmStatus}</p></div></section>
      <section><h3 className="mb-3 text-sm font-semibold">Timeline</h3><div className="space-y-3 border-l border-[var(--line)] pl-4"><Timeline title="Lead acquired" when={date(row.lead.date)} detail={row.lead.source+" · "+row.lead.campaign}/>{row.appointments.map((a,i)=><Timeline key={"a"+i} title={a.completedAt?"Visit completed":"Visit scheduled"} when={dateTime(a.completedAt??a.scheduledAt)} detail={a.noShow?"No-show":a.status}/>)}{row.offers.map(o=><Timeline key={o.id} title={"Offer "+o.number} when={o.sentAt?"Sent "+dateTime(o.sentAt):"Created "+date(o.date)+" · send not verified"} detail={formatCurrency(o.priceExclVat)+" excl. VAT · "+formatCurrency(o.priceInclVat)+" incl. VAT · "+o.status+(o.followUpAt?" · follow-up "+dateTime(o.followUpAt):"")}/>)}{row.isSigned&&<Timeline title="CRM signed" when="CRM evidence" detail="Kept separate from commercial verification."/>}{row.projects.map(p=><Timeline key={p.id} title={"Commercial project "+p.externalId} when="ROBAWS evidence" detail={formatCurrency(p.valueInclVat)+" · "+p.status}/>)}{row.invoices.map(i=><Timeline key={i.id} title={"Invoice "+i.number} when={i.date?date(i.date):"Commercial evidence"} detail={formatCurrency(i.totalInclVat)+" invoiced · "+formatCurrency(i.paidTotal)+" paid · "+i.status}/>)}</div></section>
      {row.stage==="lost"&&<div className="border border-rose-200 bg-rose-50 p-4 text-sm text-rose-900"><b>Lost / not relevant</b><p className="mt-1">{row.lostReason||"No structured reason recorded."}</p></div>}
    </div>
  </aside></div>;
}
function Timeline({title,when,detail}:{title:string;when:string;detail:string}){return <div><div className="flex flex-wrap items-center gap-2"><strong className="text-sm">{title}</strong><span className="text-xs text-[var(--muted)]">{when}</span></div><p className="mt-1 text-sm text-[var(--muted)]">{detail}</p></div>}

function Age({ label, rows }: { label:string; rows:NonNullable<CompanyDataset["commercialOffers"]> }) { return <div className="bg-white p-4"><span className="text-xs text-[var(--muted)]">{label}</span><strong className="mt-2 block">{formatCurrency(rows.reduce((n,o)=>n+o.priceInclVat,0))}</strong><small>{rows.length} offers</small></div>; }
function Mini({label,value}:{label:string;value:string}){return <div className="bg-white p-4"><span className="text-xs uppercase text-[var(--muted)]">{label}</span><strong className="mt-2 block text-lg">{value}</strong></div>}
function tone(stage:JourneyStage):"neutral"|"good"|"warn"|"bad"|"accent"{return stage==="verified"?"good":stage==="lost"?"bad":stage==="offer"||stage==="accepted"||stage==="signed"?"warn":stage==="visit"||stage==="qualified"?"accent":"neutral"}
function date(value:string){if(!value)return "—";return new Intl.DateTimeFormat("nl-BE",{day:"2-digit",month:"short",year:"numeric",timeZone:"Europe/Brussels"}).format(new Date(value.length===10?value+"T12:00:00Z":value))}
function dateTime(value:string){if(!value)return "—";return new Intl.DateTimeFormat("nl-BE",{day:"2-digit",month:"short",year:"numeric",hour:"2-digit",minute:"2-digit",timeZone:"Europe/Brussels"}).format(new Date(value))}
function monthName(value:string){const parts=value.split("-").map(Number);return new Intl.DateTimeFormat("en-GB",{month:"long",year:"numeric",timeZone:"Europe/Brussels"}).format(new Date(Date.UTC(parts[0],parts[1]-1,1)))}

"use client";

import { useMemo, useState } from "react";
import { AlertTriangle, ArrowRight, Mail, MapPin, Phone, X } from "lucide-react";
import type { CommercialInvoice, CommercialOffer, CommercialProject, CompanyDataset, Lead } from "@/lib/data/types";
import { formatCurrency, formatNumber } from "@/lib/metrics/kpis";
import { EmptyState, StatusPill } from "./ui";

type OfferTab = "open" | "accepted" | "rejected" | "all";
type SourceRow = { source: string; leads: number; matched: number; offers: number; openValue: number; rejectedValue: number; acceptedValue: number; clients: number; invoiced: number; paid: number; cost: number | null };
const verifiedMethods = new Set(["EMAIL+PHONE", "EMAIL", "PHONE", "NAME"]);
const emptyOffers: CommercialOffer[] = [];
const emptyProjects: CommercialProject[] = [];
const emptyInvoices: CommercialInvoice[] = [];

export function LeadsSalesPage({ data }: { data: CompanyDataset }) {
  const [source, setSource] = useState<string | null>(null);
  const [offerTab, setOfferTab] = useState<OfferTab>("open");
  const [selected, setSelected] = useState<Lead | null>(null);
  const offers = data.commercialOffers ?? emptyOffers;
  const projects = data.commercialProjects ?? emptyProjects;
  const invoices = data.commercialInvoices ?? emptyInvoices;
  const appointmentLeadIds = new Set(data.appointmentLeadIds ?? []);
  const robaws = data.integrations.find(item => item.provider === "robaws");
  const sourceRows = useMemo(() => buildSourceRows(data.leads, offers, projects, invoices), [data.leads, offers, projects, invoices]);
  const filteredLeads = source ? data.leads.filter(lead => lead.source === source) : data.leads;
  const filteredOffers = source ? offers.filter(offer => offer.source === source) : offers;
  const filteredProjects = source ? projects.filter(project => project.source === source) : projects;
  const filteredInvoices = source ? invoices.filter(invoice => invoice.source === source) : invoices;
  const attributedProjects = filteredProjects.filter(project => !hasDateConflict(project.attributionStatus));
  const attributedInvoices = filteredInvoices.filter(invoice => !hasDateConflict(invoice.attributionStatus));
  const verifiedClients = filteredLeads.filter(lead => verifiedMethods.has(lead.robawsMatchMethod) && lead.commercialStatus === "CLIENT_WON" && !hasDateConflict(lead.attributionLevel));
  const matchedLeads = filteredLeads.filter(lead => verifiedMethods.has(lead.robawsMatchMethod));
  const openOffers = filteredOffers.filter(offer => offer.isOpen).sort((a, b) => b.priceInclVat - a.priceInclVat);
  const acceptedOffers = filteredOffers.filter(offer => offer.isAccepted);
  const invoiced = attributedInvoices.reduce((total, invoice) => total + Math.max(0, invoice.totalInclVat - invoice.creditedTotal), 0);
  const paid = sum(attributedInvoices, "paidTotal");
  const selectedOffers = selected ? offers.filter(offer => offer.leadId === selected.id) : [];
  const selectedProjects = selected ? projects.filter(project => project.leadId === selected.id) : [];
  const selectedInvoices = selected ? invoices.filter(invoice => invoice.leadId === selected.id) : [];
  const outcomeOffers = filteredOffers.filter(offer => offerTab === "all" || (offerTab === "open" && offer.isOpen) || (offerTab === "accepted" && offer.isAccepted) || (offerTab === "rejected" && offer.isRejected));
  const highestOpenValue = openOffers[0]?.priceInclVat ?? 0;
  const dateConflictLeadIds = new Set([
    ...filteredLeads.filter(lead => hasDateConflict(lead.attributionLevel)).map(lead => lead.id),
    ...filteredOffers.filter(offer => hasDateConflict(offer.attributionStatus)).map(offer => offer.leadId),
    ...filteredProjects.filter(project => hasDateConflict(project.attributionStatus)).map(project => project.leadId),
    ...filteredInvoices.filter(invoice => invoice.leadId && hasDateConflict(invoice.attributionStatus)).map(invoice => invoice.leadId as string),
  ]);
  const dateConflicts = dateConflictLeadIds.size;
  const ambiguous = filteredLeads.filter(lead => lead.robawsMatchMethod === "AMBIGUOUS").length;

  const pipeline = [
    { label: "Leads", count: filteredLeads.length, value: null },
    { label: "Site visit", count: filteredLeads.filter(lead => appointmentLeadIds.has(lead.id) || hasReachedVisit(lead)).length, value: null },
    { label: "Offer", count: new Set(filteredOffers.map(offer => offer.leadId)).size, value: sum(filteredOffers, "priceInclVat") },
    { label: "Waiting", count: new Set(openOffers.map(offer => offer.leadId)).size, value: sum(openOffers, "priceInclVat") },
    { label: "Accepted", count: new Set(acceptedOffers.map(offer => offer.leadId)).size, value: sum(acceptedOffers, "priceInclVat") },
    { label: "Project", count: new Set(attributedProjects.map(project => project.leadId)).size, value: sum(attributedProjects, "valueInclVat") },
    { label: "Invoiced", count: new Set(attributedInvoices.map(invoice => invoice.leadId).filter(Boolean)).size, value: invoiced },
    { label: "Paid", count: new Set(attributedInvoices.filter(invoice => invoice.paidTotal > 0).map(invoice => invoice.leadId).filter(Boolean)).size, value: paid },
  ];

  function focusOpenOffers(nextSource: string) {
    setSource(nextSource);
    setOfferTab("open");
    window.requestAnimationFrame(() => document.getElementById("open-opportunities")?.scrollIntoView({ behavior: "smooth", block: "start" }));
  }

  return <div className="space-y-8">
    <div className="sales-command-bar"><div><p className="sales-kicker">Commercial evidence · ROBAWS + CRM</p><p className="mt-1 text-sm text-[var(--muted)]">Every count and euro amount below comes from a stored record. Date conflicts are excluded from attributed revenue.</p></div><div className="flex flex-wrap items-center gap-2">{source && <span className="source-filter-label">Source: {source}</span>}<button className={source ? "button-secondary" : "button-primary"} onClick={() => setSource(null)}>All sources</button></div></div>

    {robaws?.status !== "Connected" && <div className="sales-data-notice"><AlertTriangle size={17} /><div><strong>ROBAWS commercial data is not connected yet.</strong><p>Lead sources are live. Offers, project values, invoices and payments remain empty until ROBAWS is connected and synced.</p></div></div>}

    <section aria-labelledby="executive-snapshot"><SectionTitle id="executive-snapshot" eyebrow="01 · Executive snapshot" title="Money and movement" description={source ? `Filtered to ${source}` : "All real CRM leads and verified ROBAWS evidence"} /><div className="sales-kpi-grid">
      <Metric label="Leads" value={formatNumber(filteredLeads.length)} note="CRM records" /><Metric label="ROBAWS matched" value={formatNumber(matchedLeads.length)} note="Email, phone or unique exact name" /><Metric label="Offers sent" value={formatNumber(filteredOffers.length)} note="Individual offers" /><Metric label="Open offer value" value={formatCurrency(sum(openOffers, "priceInclVat"), true)} note={`${openOffers.length} waiting`} money /><Metric label="Accepted project value" value={formatCurrency(sum(attributedProjects, "valueInclVat"), true)} note="Date conflicts excluded" money /><Metric label="Attributed clients" value={formatNumber(verifiedClients.length)} note="ROBAWS evidence" /><Metric label="Invoiced" value={formatCurrency(invoiced, true)} note="Net of credits · incl. VAT" money /><Metric label="Paid" value={formatCurrency(paid, true)} note="Verified attribution" money accent />
    </div></section>

    <section aria-labelledby="pipeline-value"><SectionTitle id="pipeline-value" eyebrow="02 · Sales pipeline value" title="From lead to cash" description="Counts use distinct leads at each evidence-backed stage; values use the underlying commercial documents." /><div className="pipeline-flow">{pipeline.map((stage, index) => <div className={`pipeline-node ${stage.label === "Paid" ? "pipeline-node-paid" : ""}`} key={stage.label}><div className="flex items-center justify-between gap-2"><span>{stage.label}</span>{index < pipeline.length - 1 && <ArrowRight size={14} className="pipeline-arrow" />}</div><strong>{formatNumber(stage.count)}</strong><small>{rate(stage.count, filteredLeads.length)} of leads</small>{stage.value !== null && <em>{formatCurrency(stage.value, true)}</em>}</div>)}</div></section>

    <section aria-labelledby="source-performance"><SectionTitle id="source-performance" eyebrow="03 · Source performance" title="Which sources create money?" description="Click a source to filter the full page. CAC and ROAS appear only when acquisition cost exists on every lead in that source." /><div className="analytics-table-wrap"><table className="analytics-table source-performance-table"><thead><tr><th>Source</th><th>Leads</th><th>ROBAWS matched</th><th>Offers</th><th>Open offer €</th><th>Rejected offer €</th><th>Accepted €</th><th>Clients</th><th>Lead → client</th><th>Invoiced €</th><th>Paid €</th><th>CAC</th><th>ROAS</th></tr></thead><tbody>{sourceRows.map(row => <tr key={row.source} className={source === row.source ? "is-selected" : ""}><td><button className="source-link" onClick={() => setSource(current => current === row.source ? null : row.source)}>{row.source}<span>{source === row.source ? "Filtered" : "Filter"}</span></button></td><td>{formatNumber(row.leads)}</td><td>{formatNumber(row.matched)}</td><td>{formatNumber(row.offers)}</td><td><button className="money-link" onClick={() => focusOpenOffers(row.source)}>{formatCurrency(row.openValue, true)}</button></td><td>{formatCurrency(row.rejectedValue, true)}</td><td className="font-semibold text-[var(--ink)]">{formatCurrency(row.acceptedValue, true)}</td><td>{formatNumber(row.clients)}</td><td>{rate(row.clients, row.leads)}</td><td>{formatCurrency(row.invoiced, true)}</td><td className="font-semibold text-[var(--ink)]">{formatCurrency(row.paid, true)}</td><td>{row.cost === null || !row.clients ? "—" : formatCurrency(row.cost / row.clients, true)}</td><td>{row.cost === null || !row.cost ? "—" : `${(row.paid / row.cost).toFixed(2)}×`}</td></tr>)}</tbody></table></div></section>

    <section id="open-opportunities" aria-labelledby="open-opportunities-title" className="scroll-mt-6"><SectionTitle id="open-opportunities-title" eyebrow="04 · Open sales opportunities" title="Money waiting for a decision" description="Non-final ROBAWS offers, sorted by offer price including VAT." meta={`${openOffers.length} open · ${formatCurrency(sum(openOffers, "priceInclVat"), true)}`} />
      {openOffers.length ? <div className="analytics-table-wrap"><table className="analytics-table"><thead><tr><th>Lead</th><th>Source</th><th>Service</th><th>Offer date</th><th>Days waiting</th><th>ROBAWS status</th><th>Offer price incl. VAT</th><th>Offer #</th><th>Project</th></tr></thead><tbody>{openOffers.map(offer => { const lead = data.leads.find(item => item.id === offer.leadId); return <tr key={offer.id} className={offer.daysWaiting !== null && offer.daysWaiting > 14 ? "opportunity-critical" : offer.daysWaiting !== null && offer.daysWaiting > 7 ? "opportunity-warning" : ""}><td><button className="lead-link" onClick={() => lead && setSelected(lead)}>{offer.leadName}</button></td><td>{offer.source}</td><td>{lead?.service ?? "—"}</td><td>{formatDate(offer.date)}</td><td><WaitingBadge days={offer.daysWaiting} /></td><td><StatusPill tone="warn">{offer.status}</StatusPill></td><td className="font-semibold text-[var(--ink)]">{formatCurrency(offer.priceInclVat)} {highestOpenValue > 0 && offer.priceInclVat === highestOpenValue && <span className="highest-value">Highest value</span>}</td><td>{offer.number}</td><td>{offer.projectExternalId ?? "—"}</td></tr>; })}</tbody></table></div> : <EmptyState title="No open ROBAWS offers" body={robaws?.status === "Connected" ? "No non-final offers match this source selection." : "Connect and sync ROBAWS to load offers that are waiting for a client decision."} />}
    </section>

    <section aria-labelledby="offer-outcomes"><SectionTitle id="offer-outcomes" eyebrow="05 · Offer outcomes" title="Every offer, separately" description="Multiple offers for the same client remain separate commercial records." /><div className="segmented-control" role="tablist" aria-label="Offer outcome">{(["open", "accepted", "rejected", "all"] as OfferTab[]).map(tab => <button key={tab} role="tab" aria-selected={offerTab === tab} onClick={() => setOfferTab(tab)}>{capitalize(tab)} <span>{tab === "all" ? filteredOffers.length : filteredOffers.filter(offer => tab === "open" ? offer.isOpen : tab === "accepted" ? offer.isAccepted : offer.isRejected).length}</span></button>)}</div>
      {outcomeOffers.length ? <div className="analytics-table-wrap"><table className="analytics-table"><thead><tr><th>Lead</th><th>Source</th><th>Offer #</th><th>Date</th><th>Status</th><th>Price excl. VAT</th><th>Price incl. VAT</th><th>Project</th><th>Attribution confidence</th></tr></thead><tbody>{outcomeOffers.map(offer => { const lead = data.leads.find(item => item.id === offer.leadId); return <tr key={offer.id}><td><button className="lead-link" onClick={() => lead && setSelected(lead)}>{offer.leadName}</button></td><td>{offer.source}</td><td>{offer.number}</td><td>{formatDate(offer.date)}</td><td><OutcomePill offer={offer} /></td><td>{formatCurrency(offer.priceExclVat)}</td><td className="font-semibold text-[var(--ink)]">{formatCurrency(offer.priceInclVat)}</td><td>{offer.projectExternalId ?? "—"}</td><td><Attribution value={offer.attributionStatus} /></td></tr>; })}</tbody></table></div> : <EmptyState title={`No ${offerTab} offers`} body="No ROBAWS offer records match this view." />}
    </section>

    <section aria-labelledby="verified-clients"><SectionTitle id="verified-clients" eyebrow="06 · Attributed clients" title="Source-attributable commercial customers" description="ROBAWS-confirmed clients whose source attribution is safe. Date-conflict clients remain visible elsewhere and are not silently dropped." />
      {verifiedClients.length ? <div className="analytics-table-wrap"><table className="analytics-table"><thead><tr><th>Lead</th><th>Original source</th><th>Match method</th><th>Accepted project value</th><th>Project status</th><th>Invoiced</th><th>Paid</th><th>Attribution status</th></tr></thead><tbody>{verifiedClients.map(lead => { const leadProjects = projects.filter(project => project.leadId === lead.id && !hasDateConflict(project.attributionStatus)); const leadInvoices = invoices.filter(invoice => invoice.leadId === lead.id && !hasDateConflict(invoice.attributionStatus)); return <tr key={lead.id}><td><button className="lead-link" onClick={() => setSelected(lead)}>{lead.name}</button></td><td>{lead.source}</td><td><StatusPill tone="good">{lead.robawsMatchMethod}</StatusPill></td><td>{formatCurrency(sum(leadProjects, "valueInclVat"))}</td><td>{leadProjects.map(project => project.status).filter(Boolean).join(", ") || "—"}</td><td>{formatCurrency(leadInvoices.reduce((total, invoice) => total + Math.max(0, invoice.totalInclVat - invoice.creditedTotal), 0))}</td><td>{formatCurrency(sum(leadInvoices, "paidTotal"))}</td><td><Attribution value={lead.attributionLevel} /></td></tr>; })}</tbody></table></div> : <EmptyState title="No attributed clients yet" body="A lead appears here after an EMAIL+PHONE, EMAIL, PHONE or unique exact NAME match plus commercial evidence in ROBAWS. Date-conflict clients stay outside marketing attribution." />}
    </section>

    <section className="attribution-strip" aria-labelledby="attribution-quality"><div><p className="sales-kicker">07 · Attribution quality</p><h2 id="attribution-quality">Can this revenue be trusted?</h2></div><Diagnostic label="Total CRM leads" value={filteredLeads.length} /><Diagnostic label="Matched to ROBAWS" value={matchedLeads.length} /><Diagnostic label="Unmatched" value={filteredLeads.filter(lead => !verifiedMethods.has(lead.robawsMatchMethod) && lead.robawsMatchMethod !== "AMBIGUOUS").length} /><Diagnostic label="Ambiguous" value={ambiguous} /><Diagnostic label="Attributed clients" value={verifiedClients.length} /><Diagnostic label="Date conflicts" value={dateConflicts} warn={dateConflicts > 0} /></section>

    {selected && <LeadDrawer lead={selected} offers={selectedOffers} projects={selectedProjects} invoices={selectedInvoices} onClose={() => setSelected(null)} />}
  </div>;
}

function buildSourceRows(leads: Lead[], offers: CommercialOffer[], projects: CommercialProject[], invoices: CommercialInvoice[]) {
  const sources = [...new Set(leads.map(lead => lead.source || "Unattributed"))];
  return sources.map((source): SourceRow => {
    const sourceLeads = leads.filter(lead => lead.source === source);
    const sourceOffers = offers.filter(offer => offer.source === source && !hasDateConflict(offer.attributionStatus));
    const sourceProjects = projects.filter(project => project.source === source && !hasDateConflict(project.attributionStatus));
    const sourceInvoices = invoices.filter(invoice => invoice.source === source && !hasDateConflict(invoice.attributionStatus));
    const costs = sourceLeads.map(lead => lead.acquisitionCost);
    const cost = costs.length > 0 && costs.every(value => value !== null) ? costs.reduce<number>((total, value) => total + Number(value), 0) : null;
    return { source, leads: sourceLeads.length, matched: sourceLeads.filter(lead => verifiedMethods.has(lead.robawsMatchMethod)).length, offers: sourceOffers.length, openValue: sum(sourceOffers.filter(offer => offer.isOpen), "priceInclVat"), rejectedValue: sum(sourceOffers.filter(offer => offer.isRejected), "priceInclVat"), acceptedValue: sum(sourceProjects, "valueInclVat"), clients: sourceLeads.filter(lead => verifiedMethods.has(lead.robawsMatchMethod) && lead.commercialStatus === "CLIENT_WON" && !hasDateConflict(lead.attributionLevel)).length, invoiced: sourceInvoices.reduce((total, invoice) => total + Math.max(0, invoice.totalInclVat - invoice.creditedTotal), 0), paid: sum(sourceInvoices, "paidTotal"), cost };
  }).sort((a, b) => b.paid - a.paid || b.acceptedValue - a.acceptedValue || b.leads - a.leads);
}

function SectionTitle({ id, eyebrow, title, description, meta }: { id: string; eyebrow: string; title: string; description: string; meta?: string }) { return <div className="sales-section-heading"><div><p className="sales-kicker">{eyebrow}</p><h2 id={id}>{title}</h2><p>{description}</p></div>{meta && <strong>{meta}</strong>}</div>; }
function Metric({ label, value, note, money = false, accent = false }: { label: string; value: string; note: string; money?: boolean; accent?: boolean }) { return <div className={`sales-metric ${money ? "sales-metric-money" : ""} ${accent ? "sales-metric-accent" : ""}`}><span>{label}</span><strong>{value}</strong><small>{note}</small></div>; }
function Diagnostic({ label, value, warn = false }: { label: string; value: number; warn?: boolean }) { return <div className={warn ? "diagnostic-warn" : ""}><span>{label}</span><strong>{formatNumber(value)}</strong></div>; }
function WaitingBadge({ days }: { days: number | null }) { if (days === null) return <>—</>; const tone = days > 14 ? "bad" : days > 7 ? "warn" : "neutral"; return <StatusPill tone={tone}>{days} days</StatusPill>; }
function OutcomePill({ offer }: { offer: CommercialOffer }) { return <StatusPill tone={offer.isAccepted ? "good" : offer.isRejected ? "bad" : "warn"}>{offer.status}</StatusPill>; }
function Attribution({ value }: { value: string }) { const conflict = hasDateConflict(value); return <StatusPill tone={conflict ? "bad" : value.includes("EXACT") || value === "VERIFIED" ? "good" : "neutral"}>{conflict ? "REVIEW_DATE_CONFLICT" : value}</StatusPill>; }

function LeadDrawer({ lead, offers, projects, invoices, onClose }: { lead: Lead; offers: CommercialOffer[]; projects: CommercialProject[]; invoices: CommercialInvoice[]; onClose: () => void }) {
  const attributedInvoices = invoices.filter(item => !hasDateConflict(item.attributionStatus));
  const invoiced = attributedInvoices.reduce((total, item) => total + Math.max(0, item.totalInclVat - item.creditedTotal), 0);
  const paid = sum(attributedInvoices, "paidTotal");
  return <div className="drawer-backdrop" role="presentation" onMouseDown={onClose}><aside className="drawer sales-drawer" role="dialog" aria-modal="true" aria-label={`${lead.name} commercial details`} onMouseDown={event => event.stopPropagation()}><header><div><p className="sales-kicker">Lead evidence</p><h2>{lead.name}</h2><p>{lead.source} · received {formatDate(lead.date)}</p></div><button className="icon-button" onClick={onClose} aria-label="Close lead details"><X size={18} /></button></header><div className="sales-drawer-body">
    <div className="contact-stack"><span><Mail size={15} />{lead.email || "No email"}</span><span><Phone size={15} />{lead.phone || "No phone"}</span><span><MapPin size={15} />{lead.municipality}</span></div>
    <DrawerSection title="CRM source"><DrawerRow label="Original source" value={lead.source} /><DrawerRow label="Exact Monday status" value={lead.crmStatus} /><DrawerRow label="Service" value={lead.service} /><DrawerRow label="Campaign" value={lead.campaign} /></DrawerSection>
    <DrawerSection title={`ROBAWS offers · ${offers.length}`}>{offers.length ? offers.map(offer => <div className="evidence-record" key={offer.id}><div><strong>{offer.number}</strong><StatusPill tone={offer.isAccepted ? "good" : offer.isRejected ? "bad" : "warn"}>{offer.status}</StatusPill></div><p>{formatDate(offer.date)} · excl. VAT {formatCurrency(offer.priceExclVat)} · incl. VAT <b>{formatCurrency(offer.priceInclVat)}</b></p><Attribution value={offer.attributionStatus} /></div>) : <p className="drawer-empty">No ROBAWS offers linked.</p>}</DrawerSection>
    <DrawerSection title={`Projects · ${projects.length}`}>{projects.length ? projects.map(project => <div className="evidence-record" key={project.id}><div><strong>{project.externalId}</strong><StatusPill tone="neutral">{project.status}</StatusPill></div><p>Project value {formatCurrency(project.valueInclVat)}</p><Attribution value={project.attributionStatus} /></div>) : <p className="drawer-empty">No projects linked.</p>}</DrawerSection>
    <DrawerSection title={`Invoices · ${invoices.length}`}>{invoices.length ? invoices.map(invoice => <div className="evidence-record" key={invoice.id}><div><strong>{invoice.number}</strong><StatusPill tone="neutral">{invoice.status}</StatusPill></div><p>{formatDate(invoice.date)} · invoiced {formatCurrency(invoice.totalInclVat)} · paid <b>{formatCurrency(invoice.paidTotal)}</b></p><Attribution value={invoice.attributionStatus} /></div>) : <p className="drawer-empty">No invoices linked.</p>}</DrawerSection>
    <DrawerSection title="Attributed totals"><DrawerRow label="Invoiced" value={formatCurrency(invoiced)} /><DrawerRow label="Paid" value={formatCurrency(paid)} /><DrawerRow label="Attribution" value={hasDateConflict(lead.attributionLevel) ? "REVIEW_DATE_CONFLICT — excluded from source revenue" : lead.attributionLevel} /></DrawerSection>
  </div></aside></div>;
}

function DrawerSection({ title, children }: { title: string; children: React.ReactNode }) { return <section className="drawer-section"><h3>{title}</h3><div>{children}</div></section>; }
function DrawerRow({ label, value }: { label: string; value: string }) { return <div className="drawer-row"><span>{label}</span><strong>{value || "—"}</strong></div>; }
function hasReachedVisit(lead: Lead) {
  const status = lead.crmStatus.trim().toLowerCase().replace(/\s+/g, " ");
  const stage = lead.stage.trim().toLowerCase();
  return ["visit completed", "quote sent", "won"].includes(stage) ||
    ["visited offerte to be done", "offer sent", "email offerte", "signed", "offerte afgekeurd"].includes(status);
}
function hasDateConflict(value: string) { return value.includes("DATE_CONFLICT"); }
function sum<T>(rows: T[], key: keyof T) { return rows.reduce((total, row) => total + Number(row[key] ?? 0), 0); }
function rate(part: number, total: number) { return total ? `${new Intl.NumberFormat("nl-BE", { maximumFractionDigits: 1 }).format((part / total) * 100)}%` : "—"; }
function formatDate(value: string) { if (!value) return "—"; const date = new Date(value.length === 10 ? `${value}T12:00:00Z` : value); return new Intl.DateTimeFormat("nl-BE", { day: "2-digit", month: "short", year: "numeric", timeZone: "Europe/Brussels" }).format(date); }
function capitalize(value: string) { return value[0].toUpperCase() + value.slice(1); }

"use client";

import Link from "next/link";
import { useSearchParams } from "next/navigation";
import { AlertTriangle, ArrowRight, CheckCircle2, CircleDollarSign, Clock3, Database, TrendingUp } from "lucide-react";
import type { CompanyDataset } from "@/lib/data/types";
import { buildFunnelSummary, buildJourneyRows, type JourneyRow } from "@/lib/metrics/client-funnel";
import { formatCurrency, formatNumber, formatPercent, percentage, safeDivide } from "@/lib/metrics/kpis";
import { sourceBusinessRows, type SourceBusinessRow } from "./control-pages";
import { Card, KpiCard, SectionHeader, StatusPill } from "./ui";

function delta(current:number,previous:number){return previous===0?null:((current-previous)/previous)*100}

export function OverviewPage({data}:{data:CompanyDataset}) {
  const searchParams=useSearchParams();
  const month=searchParams.get("month");
  const scopedHref=(href:string)=>month?`${href}?month=${encodeURIComponent(month)}`:href;
  const rows=buildJourneyRows(data);
  const summary=buildFunnelSummary(data);
  const sources=sourceBusinessRows(data,rows);
  const paidSources=sources.filter(row=>["Meta Ads / Facebook","Google Ads","LeadAngel"].includes(row.source));
  const offers=(data.commercialOffers??[]).filter(item=>!hasDateConflict(item.attributionStatus));
  const projects=(data.commercialProjects??[]).filter(item=>!hasDateConflict(item.attributionStatus));
  const invoices=(data.commercialInvoices??[]).filter(item=>!hasDateConflict(item.attributionStatus));
  const sentOffers=offers.filter(item=>Boolean(item.sentAt));
  const openOffers=sentOffers.filter(item=>item.isOpen);
  const acceptedOffers=offers.filter(item=>item.isAccepted);
  const paid=invoices.reduce((sum,item)=>sum+item.paidTotal,0);
  const invoiced=invoices.reduce((sum,item)=>sum+Math.max(0,item.totalInclVat-item.creditedTotal),0);
  const projectValue=projects.reduce((sum,item)=>sum+Number(item.valueInclVat??0),0);
  const openValue=openOffers.reduce((sum,item)=>sum+item.priceInclVat,0);
  const acceptedValue=acceptedOffers.reduce((sum,item)=>sum+item.priceInclVat,0);
  const knownSpendRows=paidSources.filter(row=>row.spend!==null);
  const coveredSpend=knownSpendRows.reduce((sum,row)=>sum+Number(row.spend??0),0);
  const coveredLeads=knownSpendRows.reduce((sum,row)=>sum+row.leads,0);
  const coveredQualified=knownSpendRows.reduce((sum,row)=>sum+row.qualified,0);
  const coveredVisits=knownSpendRows.reduce((sum,row)=>sum+row.visits,0);
  const coveredOffers=knownSpendRows.reduce((sum,row)=>sum+row.offers,0);
  const coveredClients=knownSpendRows.reduce((sum,row)=>sum+row.attributedClients,0);
  const coveredPaid=knownSpendRows.reduce((sum,row)=>sum+row.paid,0);

  const stages=[
    {label:"Spend",value:formatCurrency(data.metrics.spend,true),note:"Tracked paid media"},
    {label:"Unique leads",value:formatNumber(summary.uniquePeople),note:formatNumber(data.metrics.leads)+" CRM rows"},
    {label:"Qualified",value:formatNumber(summary.qualified),note:formatPercent(percentage(summary.qualified,summary.uniquePeople))+" of unique people"},
    {label:"Visits",value:formatNumber(rows.filter(hasCompletedVisitEvidence).length),note:"Completed / post-visit evidence"},
    {label:"Offers sent",value:formatNumber(summary.offersSent),note:formatCurrency(summary.sentQuotedValue,true)+" sent value"},
    {label:"CRM signed",value:formatNumber(summary.crmSigned),note:"Monday status"},
    {label:"ROBAWS clients",value:formatNumber(summary.commercialClients),note:formatNumber(summary.attributableClients)+" attributable"},
    {label:"Paid",value:formatCurrency(paid,true),note:"Commercial cash"},
  ];

  const actionItems=buildActionItems(data,rows,openOffers,paidSources);
  const budgetCards=paidSources.map(source=>budgetConclusion(source));

  return <div className="space-y-6">
    <Card className="overflow-hidden">
      <div className="border-b border-[var(--line)] p-5">
        <SectionHeader title="Is marketing producing business?" description="One chain from tracked spend to paid revenue. Detailed evidence lives in the drill-down pages."/>
      </div>
      <div className="story-chain">
        {stages.map((stage,index)=><div className="story-stage" key={stage.label}><div className="flex items-center justify-between gap-2"><span>{stage.label}</span>{index<stages.length-1&&<ArrowRight size={14}/>}</div><strong>{stage.value}</strong><small>{stage.note}</small></div>)}
      </div>
    </Card>

    <div className="kpi-grid border-l border-t border-[var(--line)]">
      <KpiCard label="Marketing spend" value={formatCurrency(data.metrics.spend,true)} delta={delta(data.metrics.spend,data.previous.spend)} meta="Target: not configured"/>
      <KpiCard label="Unique leads" value={formatNumber(summary.uniquePeople)} meta={formatNumber(data.metrics.leads)+" CRM rows · target not configured"}/>
      <KpiCard label="Qualified people" value={formatNumber(summary.qualified)} meta={formatPercent(percentage(summary.qualified,summary.uniquePeople))+" of unique people"}/>
      <KpiCard label="Visits" value={formatNumber(rows.filter(hasCompletedVisitEvidence).length)} meta="Deduplicated visit evidence"/>
      <KpiCard label="Won project value" value={formatCurrency(projectValue,true)} delta={delta(projectValue,data.previous.revenue)} meta={formatNumber(summary.attributableClients)+" attributable clients"}/>
      <KpiCard label="Open pipeline" value={formatCurrency(openValue,true)} meta={formatNumber(openOffers.length)+" sent + open offers"}/>
      <KpiCard label="Invoiced" value={formatCurrency(invoiced,true)} meta="Net of credits"/>
      <KpiCard label="Paid" value={formatCurrency(paid,true)} meta="Cash received"/>
    </div>

    <Card className="p-5">
      <SectionHeader title="Economics with complete cost coverage" description="Cost KPIs include only sources whose spend is actually available; missing spend never becomes €0."/>
      <div className="economics-grid">
        <Economy label="Covered spend" value={formatCurrency(coveredSpend)} note={knownSpendRows.map(row=>row.source).join(", ")||"No paid source fully covered"}/>
        <Economy label="CPL" value={formatCurrency(safeDivide(coveredSpend,coveredLeads))} note={coveredLeads+" covered leads"}/>
        <Economy label="Cost / qualified" value={formatCurrency(safeDivide(coveredSpend,coveredQualified))} note={coveredQualified+" qualified"}/>
        <Economy label="Cost / visit" value={formatCurrency(safeDivide(coveredSpend,coveredVisits))} note={coveredVisits+" visits"}/>
        <Economy label="Cost / offer" value={formatCurrency(safeDivide(coveredSpend,coveredOffers))} note={coveredOffers+" sent offers"}/>
        <Economy label="CAC" value={formatCurrency(safeDivide(coveredSpend,coveredClients))} note={coveredClients+" attributable clients"}/>
        <Economy label="Paid ROAS" value={coveredSpend?formatNumber(coveredPaid/coveredSpend)+"×":"—"} note={formatCurrency(coveredPaid)+" paid cash"}/>
      </div>
    </Card>

    <div className="grid gap-6 xl:grid-cols-[1.15fr_.85fr]">
      <Card className="p-5">
        <SectionHeader title="What requires action?" description="The dashboard states the issue; management should not have to calculate it manually."/>
        <div className="space-y-3">
          {actionItems.length?actionItems.map(item=><ActionItem key={item.title} {...item} href={scopedHref(item.href)}/>):<div className="flex items-center gap-3 border border-emerald-200 bg-emerald-50 p-4 text-sm text-emerald-900"><CheckCircle2 size={18}/><strong>No critical action rule is triggered by the current evidence.</strong></div>}
        </div>
      </Card>

      <Card className="p-5">
        <SectionHeader title="Revenue stages" description="Offer value, project value, invoiced and paid are different commercial states."/>
        <div className="space-y-1">
          <MoneyRow label="Total offered" value={sentOffers.reduce((sum,item)=>sum+item.priceInclVat,0)}/>
          <MoneyRow label="Open pipeline" value={openValue}/>
          <MoneyRow label="Accepted / contracted" value={acceptedValue}/>
          <MoneyRow label="Project value" value={projectValue}/>
          <MoneyRow label="Invoiced" value={invoiced}/>
          <MoneyRow label="Paid" value={paid} accent/>
        </div>
        <Link href={scopedHref("/revenue")} className="mt-4 inline-flex items-center gap-2 text-sm font-semibold underline underline-offset-4">Open revenue evidence <ArrowRight size={14}/></Link>
      </Card>
    </div>

    <Card className="p-5">
      <SectionHeader title="Budget conclusions" description="These rules use client and cash evidence, not lead volume or CTR alone."/>
      <div className="grid gap-4 lg:grid-cols-3">
        {budgetCards.map(card=><BudgetCard key={card.source} {...card}/>)}
      </div>
      <Link href={scopedHref("/campaigns")} className="mt-5 inline-flex items-center gap-2 text-sm font-semibold underline underline-offset-4">Open full source & campaign economics <ArrowRight size={14}/></Link>
    </Card>

    <Card className="p-5">
      <SectionHeader title="Data trust" description="Performance conclusions are separated from data-quality blockers."/>
      <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-4">
        <Trust label="Google Ads spend" ok={!paidSources.some(row=>row.source==="Google Ads"&&row.costState==="missing")} detail={paidSources.some(row=>row.source==="Google Ads"&&row.costState==="missing")?"Missing — no CAC/ROAS":"Available or no Google cohort"}/>
        <Trust label="LeadAngel cost" ok={!paidSources.some(row=>row.source==="LeadAngel"&&row.costState==="missing")} detail={paidSources.some(row=>row.source==="LeadAngel"&&row.costState==="missing")?"Missing — ROI blocked":"Available or no LeadAngel cohort"}/>
        <Trust label="Potential duplicates" ok={data.dataHealth.duplicates===0} detail={data.dataHealth.duplicates+" flagged"}/>
        <Trust label="Signed reconciliation" ok={rows.filter(row=>row.isSigned&&!row.isCommercialClient).length===0} detail={rows.filter(row=>row.isSigned&&!row.isCommercialClient).length+" signed not ROBAWS-confirmed"}/>
      </div>
      <Link href={scopedHref("/data-health")} className="mt-5 inline-flex items-center gap-2 text-sm font-semibold underline underline-offset-4">Open data health <ArrowRight size={14}/></Link>
    </Card>
  </div>;
}

function buildActionItems(data:CompanyDataset,rows:JourneyRow[],openOffers:NonNullable<CompanyDataset["commercialOffers"]>,sources:SourceBusinessRow[]) {
  const items:Array<{title:string;body:string;tone:"bad"|"warn"|"good";href:string;icon:"clock"|"data"|"money"|"trend"}>=[];
  const stale=openOffers.filter(item=>(item.daysWaiting??0)>7);
  const staleValue=stale.reduce((sum,item)=>sum+item.priceInclVat,0);
  if(stale.length)items.push({title:stale.length+" open offers are older than 7 days",body:formatCurrency(staleValue)+" of open commercial value needs review or follow-up.",tone:"bad",href:"/offers-pipeline",icon:"clock"});
  const signedUnconfirmed=rows.filter(row=>row.isSigned&&!row.isCommercialClient);
  if(signedUnconfirmed.length)items.push({title:signedUnconfirmed.length+" signed leads are not confirmed as ROBAWS clients",body:"Reconcile the CRM and ROBAWS records before judging source CAC or revenue.",tone:"warn",href:"/data-health",icon:"data"});
  const missingCost=sources.filter(row=>row.costState==="missing");
  if(missingCost.length)items.push({title:"Paid-source spend is incomplete",body:missingCost.map(row=>row.source).join(", ")+" cannot be compared on CAC or ROAS yet.",tone:"warn",href:"/data-health",icon:"money"});
  const visitsNoOffer=rows.filter(row=>hasCompletedVisitEvidence(row)&&!row.offers.length&&!row.isCommercialClient);
  if(visitsNoOffer.length)items.push({title:visitsNoOffer.length+" visited leads have no ROBAWS offer linked",body:"Check quote creation / linking before assuming these opportunities were lost.",tone:"warn",href:"/funnel",icon:"trend"});
  if(data.dataHealth.missingCampaign>0)items.push({title:data.dataHealth.missingCampaign+" leads are missing campaign attribution",body:"Campaign conclusions exclude or weaken these records.",tone:"warn",href:"/data-health",icon:"data"});
  return items.slice(0,5);
}

function budgetConclusion(row:SourceBusinessRow){
  const paidRoas=row.spend&&row.spend>0?row.paid/row.spend:null;
  let action="Monitor";
  let body="There is not enough commercial evidence for a budget change.";
  let tone:"good"|"warn"|"bad"="warn";
  if(row.costState==="missing"){
    action="Fix spend tracking";
    body=`${row.leads} leads, ${row.commercialClients} ROBAWS clients and ${formatCurrency(row.paid)} paid cash are visible, but acquisition cost is missing.`;
  }else if(row.spend!==null&&row.attributedClients===0&&row.openValue>0){
    action="Hold";
    body=`${formatCurrency(row.spend)} spent. No attributable client yet, but ${formatCurrency(row.openValue)} remains in open pipeline.`;
  }else if(row.spend!==null&&row.attributedClients===0){
    action="Do not increase";
    tone="bad";
    body=`${formatCurrency(row.spend)} spent with no attributable commercial client in the selected cohort.`;
  }else if(row.spend!==null&&row.attributedClients===1&&paidRoas!==null&&paidRoas>=3){
    action="Scale cautiously";
    tone="good";
    body=`${formatCurrency(row.spend)} spend → ${formatCurrency(row.paid)} paid cash (${formatNumber(paidRoas)}×), but the result is concentrated in one attributable client.`;
  }else if(row.spend!==null&&row.attributedClients>1&&paidRoas!==null&&paidRoas>=3){
    action="Evidence supports increase";
    tone="good";
    body=`${row.attributedClients} attributable clients and ${formatNumber(paidRoas)}× paid ROAS provide broader evidence than CPL alone.`;
  }else if(row.spend!==null){
    action="Hold / improve";
    body=`${row.attributedClients} attributable clients, ${formatCurrency(row.openValue)} open pipeline and ${formatCurrency(row.paid)} paid cash from ${formatCurrency(row.spend)} spend.`;
  }
  return {source:row.source,action,body,tone};
}

function hasCompletedVisitEvidence(row:JourneyRow){
  const status=row.lead.crmStatus.trim().toLowerCase().replace(/\s+/g," ");
  const stage=row.lead.stage.trim().toLowerCase();
  return row.appointments.some(item=>Boolean(item.completedAt))||stage.includes("visit completed")||stage.includes("quote")||stage.includes("won")||["visited offerte to be done","offer sent","email offerte","signed","offerte afgekeurd"].includes(status);
}
function ActionItem({title,body,tone,href,icon}:{title:string;body:string;tone:"bad"|"warn"|"good";href:string;icon:"clock"|"data"|"money"|"trend"}){
  const Icon=icon==="clock"?Clock3:icon==="data"?Database:icon==="money"?CircleDollarSign:TrendingUp;
  const cls=tone==="bad"?"border-rose-200 bg-rose-50 text-rose-900":tone==="good"?"border-emerald-200 bg-emerald-50 text-emerald-900":"border-amber-200 bg-amber-50 text-amber-900";
  return <Link href={href} className={`flex gap-3 border p-4 ${cls}`}><Icon size={18} className="mt-0.5 shrink-0"/><div><strong className="text-sm">{title}</strong><p className="mt-1 text-sm leading-5 opacity-80">{body}</p></div><ArrowRight size={15} className="ml-auto mt-0.5 shrink-0"/></Link>;
}
function BudgetCard({source,action,body,tone}:{source:string;action:string;body:string;tone:"good"|"warn"|"bad"}){
  const cls=tone==="good"?"border-emerald-200 bg-emerald-50":tone==="bad"?"border-rose-200 bg-rose-50":"border-amber-200 bg-amber-50";
  return <div className={`border p-4 ${cls}`}><div className="flex items-start justify-between gap-3"><strong className="text-sm">{source}</strong><StatusPill tone={tone}>{action}</StatusPill></div><p className="mt-3 text-sm leading-6">{body}</p></div>;
}
function Economy({label,value,note}:{label:string;value:string;note:string}){return <div className="economy-cell"><span>{label}</span><strong>{value}</strong><small>{note}</small></div>}
function MoneyRow({label,value,accent=false}:{label:string;value:number;accent?:boolean}){return <div className={`money-row ${accent?"money-row-accent":""}`}><span>{label}</span><strong>{formatCurrency(value)}</strong></div>}
function Trust({label,ok,detail}:{label:string;ok:boolean;detail:string}){return <div className="trust-card"><div className="flex items-center gap-2">{ok?<CheckCircle2 size={16} className="text-emerald-700"/>:<AlertTriangle size={16} className="text-amber-700"/>}<strong>{label}</strong></div><p>{detail}</p></div>}
function hasDateConflict(value:string|null|undefined){return String(value??"").toUpperCase().includes("DATE_CONFLICT")}

"use client";

import Link from "next/link";
import { usePathname, useSearchParams } from "next/navigation";
import { Bell, CircleHelp, PanelLeftClose, Settings } from "lucide-react";
import { navItems } from "./icons";

export function Sidebar() {
  const pathname = usePathname();
  const searchParams = useSearchParams();
  const month = searchParams.get("month");
  const hrefWithMonth = (href: string) => month ? `${href}?month=${encodeURIComponent(month)}` : href;
  return (
    <aside className="sidebar print:hidden">
