export function parseProvider(value: string): IntegrationProvider | null {
  return value in providerCatalog ? value as IntegrationProvider : null;
}

export async function missingProviderConfiguration(provider: IntegrationProvider) {
  const group = providerCatalog[provider].authorizationGroup;

  if (group === "google") {
    return await isGoogleAppConfigured()
      ? []
      : ["Google application configuration in Supabase Vault"];
  }

  const requirements: Record<ProviderDefinition["authorizationGroup"], string[]> = {
    meta: ["META_APP_ID", "META_APP_SECRET"],
    google: [],
    monday: ["MONDAY_API_TOKEN"],
    hubspot: ["HUBSPOT_ACCESS_TOKEN"],
    robaws: ["ROBAWS_API_KEY", "ROBAWS_API_SECRET"],
    website: [],
  };

  const missing = requirements[group].filter((name) => !process.env[name]);

  if (
    group === "website" &&
    !process.env.SUPABASE_SECRET_KEY &&
    !process.env.SUPABASE_SERVICE_ROLE_KEY
  ) {
    missing.push("SUPABASE_SECRET_KEY");
  }

  return missing;
}

import "server-only";

import { createSupabaseAdminClient } from "@/lib/supabase/admin";
import type { IntegrationProvider } from "./types";

export type ProviderCredential = {
  accessToken: string;
  refreshToken?: string;
  expiresAt?: string;
  scopes: string[];
  permissionStatuses?: Record<string, string>;
};

export interface CredentialStore {
  readonly ready: boolean;
  read(
    connectionId: string,
    provider: IntegrationProvider,
  ): Promise<ProviderCredential | null>;
  write(
    connectionId: string,
    provider: IntegrationProvider,
    credential: ProviderCredential,
  ): Promise<void>;
  remove(
    connectionId: string,
    provider: IntegrationProvider,
  ): Promise<void>;
}

type StoredCredential = {
  provider: IntegrationProvider;
  credential: ProviderCredential;
};

class SupabaseVaultCredentialStore implements CredentialStore {
  readonly ready = true;

  async read(
    connectionId: string,
    provider: IntegrationProvider,
  ): Promise<ProviderCredential | null> {
    const supabase = createSupabaseAdminClient();

    const { data, error } = await supabase.rpc(
      "reporting_get_integration_secret",
      {
        p_connection_id: connectionId,
      },
    );

    if (error) {
      throw new Error(`Unable to read integration credential: ${error.message}`);
    }

    if (!data) return null;

    const stored = JSON.parse(data as string) as StoredCredential;

    if (stored.provider !== provider) {
      throw new Error("Stored integration credential provider mismatch.");
    }

    return stored.credential;
  }

  async write(
    connectionId: string,
    provider: IntegrationProvider,
    credential: ProviderCredential,
  ): Promise<void> {
    const supabase = createSupabaseAdminClient();

    const payload: StoredCredential = {
      provider,
      credential,
    };

    const { error } = await supabase.rpc(
      "reporting_put_integration_secret",
      {
        p_connection_id: connectionId,
        p_secret: JSON.stringify(payload),
      },
    );

    if (error) {
      throw new Error(`Unable to store integration credential: ${error.message}`);
    }
  }

  async remove(
    connectionId: string,
    provider: IntegrationProvider,
  ): Promise<void> {
    const existing = await this.read(connectionId, provider);

    if (!existing) return;

    const supabase = createSupabaseAdminClient();

    const { error } = await supabase.rpc(
      "reporting_delete_integration_secret",
      {
        p_connection_id: connectionId,
      },
    );

    if (error) {
      throw new Error(`Unable to remove integration credential: ${error.message}`);
    }
  }
}

export const credentialStore: CredentialStore =
  new SupabaseVaultCredentialStore();

