export async function syncCrmProvider(
  provider: IntegrationProvider,
  companyId: string,
  configuration: Record<string, unknown>,
): Promise<SyncResult> {
  const admin = createSupabaseAdminClient();
  const lookups = await loadLookups(admin, companyId);

  if (provider === "monday") {
    return syncMonday(admin, companyId, configuration, lookups);
  }

  if (provider === "hubspot") {
    return syncHubSpot(admin, companyId, lookups);
  }

  throw new Error(`${provider} CRM sync is not implemented yet.`);
}

async function loadLookups(
  admin: AdminClient,
  companyId: string,
): Promise<LookupMaps> {
  const companyResult = await admin
    .from("companies")
    .select("organization_id")
    .eq("id", companyId)
    .single();

  if (companyResult.error) {
    throw new Error(companyResult.error.message);
  }

  const [channelsResult, servicesResult] = await Promise.all([
    admin
      .from("marketing_channels")
      .select("id,name")
      .eq("organization_id", companyResult.data.organization_id),
    admin
      .from("services")
      .select("id,name")
      .eq("company_id", companyId)
      .eq("is_active", true),
  ]);

  if (channelsResult.error) {
    throw new Error(channelsResult.error.message);
  }

  if (servicesResult.error) {
    throw new Error(servicesResult.error.message);
  }

  return {
    channels: new Map(
      (channelsResult.data ?? []).map((row) => [
        normalize(String(row.name)),
        String(row.id),
      ]),
    ),
    services: new Map(
      (servicesResult.data ?? []).map((row) => [
        normalize(String(row.name)),
        String(row.id),
      ]),
    ),
  };
}

