      source: rawSource || null,
      channel_id: channelForMonday(rawSource, lookups.channels),
      service_id: serviceForIsoprotech(rawService, lookups.services),
      municipality:
        rawLocation && !looksLikePostalCode(rawLocation)
          ? rawLocation
          : null,
      postal_code:
        rawLocation && looksLikePostalCode(rawLocation)
          ? rawLocation
          : null,
      sales_stage: stage,
      crm_status: rawStatus || null,
      notes: notes || null,
      closed_at:
        stage === "won" || stage === "lost"
          ? new Date().toISOString()
          : null,
      lost_reason: stage === "lost" ? rejection || rawStatus || null : null,
      crm_source: "monday",
      crm_external_id: item.id,
    };
  });

  const imported = await upsertLeads(admin, leads);

  const dealItems = await fetchAllMondayItems(
    token,
    "5094302335",
  );

  const dealRows = dealItems.map((item) => {
    const columns = new Map(
      item.column_values.map((column) => [
        column.id,
        column.text ?? column.value ?? "",
      ]),
    );

    const group =
      clean(item.group?.title);

    const rawStage =
      clean(columns.get("deal_stage"));

    const groupKey = normalize(group);

    const stage =
      groupKey.includes("closed won")
        ? "won"
        : groupKey.includes("closed lost")
          ? "lost"
          : groupKey.includes("waiting") ||
              groupKey.includes("on hold")
            ? "on_hold"
            : rawStage || "open";

    return {
      company_id: companyId,
      crm_source: "monday",
      crm_external_id: item.id,
      name: item.name,
      stage,
      pipeline_group: group || null,
      deal_value: numberOrNull(
        clean(columns.get("deal_value")),
      ),
      offer_status:
        clean(
          columns.get("color_mm3h4jj0"),
        ) || null,
      offer_number:
        clean(
          columns.get("text_mm3hn5gm"),
        ) || null,
      lost_reason:
        clean(
          columns.get("color_mm3han24"),
        ) || null,
      created_at_external:
        crmDate(undefined, item.created_at),
      updated_at: new Date().toISOString(),
    };
  });

  const dealResult = await admin
    .from("crm_deals")
    .upsert(dealRows, {
      onConflict:
        "company_id,crm_source,crm_external_id",
    })
    .select("id");

  if (dealResult.error) {
    throw new Error(
      `Unable to import Monday deals: ${dealResult.error.message}`,
    );
  }

  const dealsImported =
    dealResult.data?.length ?? 0;

  return {
    recordsImported:
      imported.length + dealsImported,
    leadsImported: imported.length,
    dealsImported,
    projectsImported: 0,
    revenueImported: 0,
  };
}

async function fetchAllMondayItems(
  token: string,
  boardId: string,
): Promise<MondayItem[]> {
  const all: MondayItem[] = [];

  const firstQuery = `
    query ($ids: [ID!]!) {
      boards(ids: $ids) {
        items_page(limit: 100) {
          cursor
          items {
            id
            name
            created_at
            group {
              id
              title
            }
            column_values {
              id
              text
              value
            }
          }
        }
      }
    }
  `;

  const first = await mondayRequest<{
    boards?: Array<{ items_page?: MondayPage }>;
  }>(token, firstQuery, { ids: [boardId] });

  const firstPage = first.boards?.[0]?.items_page;

  if (!firstPage) {
    throw new Error(`Monday board ${boardId} returned no items_page.`);
  }

  all.push(...firstPage.items);

  let cursor = firstPage.cursor ?? null;

  while (cursor) {
    const nextQuery = `
      query ($cursor: String!) {
        next_items_page(limit: 100, cursor: $cursor) {
          cursor
          items {
            id
            name
            created_at
            group {
              id
              title
            }
            column_values {
              id
              text
              value
            }
          }
        }
      }
    `;

    const next = await mondayRequest<{
      next_items_page?: MondayPage;
    }>(token, nextQuery, { cursor });

    const page = next.next_items_page;

    if (!page) break;

    all.push(...page.items);
    cursor = page.cursor ?? null;
  }

  return all;
}

async function mondayRequest<T>(
  token: string,
  query: string,
  variables: Record<string, unknown>,
): Promise<T> {
  const response = await fetch("https://api.monday.com/v2", {
    method: "POST",
    headers: {
      Authorization: token,
      "Content-Type": "application/json",
      "API-Version": "2026-07",
    },
    body: JSON.stringify({ query, variables }),
    cache: "no-store",
  });

  const json = await response.json() as {
    data?: T;
    errors?: Array<{ message?: string }>;
  };

  if (!response.ok || json.errors?.length || !json.data) {
    throw new Error(
      json.errors?.map((error) => error.message).join("; ") ||
      `Monday API returned HTTP ${response.status}.`,
    );
  }

  return json.data;
}

