async function fetchAllHubSpotDeals(
  token: string,
): Promise<HubSpotDeal[]> {
  const properties = [
    "dealname",
    "pipeline",
    "dealstage",
    "amount_in_home_currency",
    "hs_is_closed_won",
    "hs_is_closed_lost",
    "closedate",
