  return fetchHubSpotObjects<HubSpotDeal>(
    token,
    "deals",
    properties,
    "contacts",
  );
}

async function fetchHubSpotObjects<T>(
  token: string,
  objectType: string,
  properties: string[],
  associations: string,
): Promise<T[]> {
  const all: T[] = [];
  let after: string | undefined;

  do {
    const url = new URL(
      `https://api.hubapi.com/crm/v3/objects/${objectType}`,
    );

    url.searchParams.set("limit", "100");
    url.searchParams.set(
      "properties",
      properties.join(","),
    );
    url.searchParams.set(
      "associations",
      associations,
    );

    if (after) {
      url.searchParams.set("after", after);
    }

    const response = await fetch(url, {
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": "application/json",
      },
      cache: "no-store",
    });

    const json = await response.json() as HubSpotPage<T> & {
      message?: string;
    };

    if (!response.ok) {
      throw new Error(
        json.message ||
        `HubSpot API returned HTTP ${response.status}.`,
      );
    }

    all.push(...(json.results ?? []));
    after = json.paging?.next?.after;
  } while (after);

  return all;
}

