function mondayStage(
  status?: string,
  rejection?: string,
) {
  const value = normalize(
    [status, rejection]
      .filter(Boolean)
      .join(" "),
  );

  if (
    includesAny(value, [
      "signed",
      "gewonnen",
      "akkoord",
      "contract",
      "accepted",
      "won",
    ])
  ) return "won";

  if (
    includesAny(value, [
      "offerte afgekeurd",
      "afgewezen",
      "verloren",
      "geen interesse",
      "niet interessant",
      "wrong region",
      "verkeerde regio",
      "verkeerde nummer",
      "onjuiste contactgegevens",
      "heeft al iemand gevonden",
      "afspraak geannuleerd",
      "incorrect contact",
      "rejected",
      "lost",
    ])
  ) return "lost";

  if (
    includesAny(value, [
      "offer sent",
      "email offerte",
      "offerte",
      "proposal",
      "quote",
      "onderhandeling",
    ])
  ) return "quote_sent";

  if (
    includesAny(value, [
      "visited offerte to be done",
      "bezoek uitgevoerd",
      "afspraak uitgevoerd",
      "visit completed",
    ])
  ) return "visit_completed";

  if (
    includesAny(value, [
      "afspraak ingeboekt",
      "bezoek gepland",
      "afspraak",
      "visit booked",
    ])
  ) return "visit_booked";

  if (
    includesAny(value, [
      "qualified",
      "gekwalificeerd",
    ])
  ) return "qualified";

  if (
    includesAny(value, [
      "opvolgen",
      "terug bellen",
      "voicemail",
      "gebeld",
      "contact",
      "onbereikbaar",
      "bereikt",
      "email verstuurd",
      "info email",
    ])
  ) return "contacted";

  return "new";
}

function hubSpotCrmStatus(
  contact: Record<string, string | null | undefined>,
  deal?: HubSpotDeal,
) {
  if (deal) {
    const stage = clean(deal.properties.dealstage);

    const labels: Record<string,string> = {
      "5229984993": "Lead Identified",
      "5229984994": "Initial Consultation",
      "5229984995": "Proposal Sent",
      "5229984996": "Negotiation",
      "5229984997": "Contract Signed",
      closedwon: "Closed Won",
      closedlost: "Closed Lost",
    };

    if (stage) {
      return labels[stage] ?? stage;
    }
  }

  return (
    clean(contact.hs_lead_status) ||
    clean(contact.lifecyclestage) ||
    null
  );
}

function hubSpotStage(
  contact: Record<string, string | null | undefined>,
  deal?: HubSpotDeal,
) {
  if (deal) {
    const stage = clean(deal.properties.dealstage);

    if (
      clean(deal.properties.hs_is_closed_won) === "true" ||
      stage === "closedwon" ||
      stage === "5229984997"
    ) return "won";

    if (
      clean(deal.properties.hs_is_closed_lost) === "true" ||
      stage === "closedlost"
    ) return "lost";

    if (
      stage === "5229984995" ||
      stage === "5229984996"
    ) return "quote_sent";

    if (stage === "5229984994") {
      return "visit_booked";
    }

    if (stage === "5229984993") {
      return "qualified";
    }
  }

  const leadStatus = normalize(contact.hs_lead_status);
  const lifecycle = normalize(contact.lifecyclestage);

  if (lifecycle === "customer") return "won";

  if (
    includesAny(leadStatus, [
      "unqualified",
      "bad timing",
    ])
  ) return "lost";

  if (leadStatus === "open deal") {
    return "qualified";
  }

  if (
    includesAny(leadStatus, [
      "attempted to contact",
      "connected",
      "in progress",
      "open",
    ])
  ) return "contacted";

  if (
    lifecycle === "opportunity" ||
    lifecycle === "salesqualifiedlead" ||
    lifecycle === "marketingqualifiedlead"
  ) return "qualified";

  return "new";
}

function channelForMonday(
  source: string,
  channels: Map<string, string>,
) {
  const value = normalize(source);

  if (
    value.includes("facebook") ||
    value.includes("meta") ||
    value.includes("instagram")
  ) {
    return channels.get(normalize("Meta Ads")) ?? null;
  }

  if (
    value.includes("google ads") ||
    value.includes("google ad")
  ) {
    return channels.get(normalize("Google Ads")) ?? null;
  }

  if (value.includes("referral")) {
    return channels.get(normalize("Referral")) ?? null;
  }

  return null;
}

function channelForHubSpot(
  source: string,
  channels: Map<string, string>,
) {
  const value = normalize(source);

  const channelName =
    value === "paid social" ? "Meta Ads" :
    value === "paid search" ? "Google Ads" :
    value === "organic search" ? "Google Organic" :
    value === "social media" ? "Instagram / Facebook Organic" :
    value === "referrals" ? "Referral" :
    value === "direct traffic" ? "Direct" :
    null;

  return channelName
    ? channels.get(normalize(channelName)) ?? null
    : null;
}

function hubSpotSourceLabel(source: string) {
  const labels: Record<string, string> = {
    PAID_SOCIAL: "Paid Social",
    PAID_SEARCH: "Paid Search",
    ORGANIC_SEARCH: "Organic Search",
    SOCIAL_MEDIA: "Organic Social",
    REFERRALS: "Referral",
    DIRECT_TRAFFIC: "Direct",
    EMAIL_MARKETING: "Email Marketing",
    OTHER_CAMPAIGNS: "Other Campaign",
    OFFLINE: "Offline",
    AI_REFERRALS: "AI Referral",
  };

  return labels[source] ?? source;
}

function serviceForIsoprotech(
  raw: string,
  services: Map<string, string>,
) {
  const value = normalize(raw);

  const name =
    value.includes("gevelisolatie") ? "Gevelisolatie" :
    value.includes("gevelrenovatie") ? "Gevelrenovatie" :
    value.includes("dakisolatie") ? "Dakisolatie" :
    value.includes("dakrenovatie") ? "Dakrenovatie" :
    value.includes("dakkapel") ? "Dakkapel" :
    value.includes("asbest") ? "Asbest" :
    null;

  return name
    ? services.get(normalize(name)) ?? null
    : null;
}

function serviceForReno(
  raw: string,
  services: Map<string, string>,
) {
  const value = normalize(raw);

  const name =
    value.includes("badkamer") ||
    value.includes("bathroom")
      ? "Badkamerrenovatie"
    : value.includes("totaal") ||
      value.includes("total renovation")
      ? "Totaalrenovatie"
    : value.includes("gyproc") ||
      value.includes("pleister")
      ? "Gyproc / pleisterwerken"
    : value.includes("vloer")
      ? "Vloeren"
    : value.includes("schilder")
      ? "Schilderwerken"
    : value.includes("tegel")
      ? "Tegelwerken"
    : value.includes("interieur")
      ? "Interieurafwerking"
    : null;

  return name
    ? services.get(normalize(name)) ?? null
    : null;
}

function isWonDeal(deal: HubSpotDeal) {
  return (
    clean(deal.properties.hs_is_closed_won) === "true" ||
    clean(deal.properties.dealstage) === "closedwon"
  );
}

function isSampleDeal(deal: HubSpotDeal) {
  return normalize(clean(deal.properties.dealname))
    .includes("sample deal");
}

function compareDeals(a: HubSpotDeal, b: HubSpotDeal) {
  const aWon = isWonDeal(a) ? 1 : 0;
  const bWon = isWonDeal(b) ? 1 : 0;

  if (aWon !== bWon) return bWon - aWon;

  const aDate = Date.parse(
    clean(a.properties.closedate) ||
    clean(a.properties.createdate) ||
    "1970-01-01",
  );

  const bDate = Date.parse(
    clean(b.properties.closedate) ||
    clean(b.properties.createdate) ||
    "1970-01-01",
  );

  return bDate - aDate;
}

// =========================================================
// GENERAL HELPERS
// =========================================================

function crmDate(
  dateText?: string,
  fallback?: string,
) {
  if (dateText) {
    if (/^\d{4}-\d{2}-\d{2}$/.test(dateText)) {
      return `${dateText}T12:00:00.000Z`;
    }

    const parsed = Date.parse(dateText);
    if (Number.isFinite(parsed)) {
      return new Date(parsed).toISOString();
    }
  }

  if (fallback) {
    const parsed = Date.parse(fallback);
    if (Number.isFinite(parsed)) {
      return new Date(parsed).toISOString();
    }
  }

  return new Date().toISOString();
}

function numberOrNull(value?: string | null) {
  if (!value) return null;

  const number = Number(
    value.replace(/[^0-9,.-]/g, "").replace(",", "."),
  );

  return Number.isFinite(number)
    ? number
    : null;
}

function looksLikePostalCode(value: string) {
  return /^\d{4}$/.test(value.trim());
}

function normalize(value?: string | null) {
  return (value ?? "")
    .trim()
    .toLowerCase()
    .replace(/[_-]+/g, " ")
    .replace(/\s+/g, " ");
}

function includesAny(
  value: string,
  needles: string[],
) {
  return needles.some((needle) =>
    value.includes(normalize(needle)),
  );
}

function clean(value?: string | null) {
  return (value ?? "").trim();
}

function required(name: string) {
  const value = process.env[name];

  if (!value || value === "[SENSITIVE]") {
    throw new Error(`Missing server setting: ${name}`);
  }

  return value;
}

import "server-only";

import { googleJson } from "../google/client";
import { normalizeGa4Row, type Ga4Metric } from "../google/core";

export type Ga4Resource = {
  id: string;
  name: string;
  property_id: string;
  account_id: string;
  account_name: string;
};

export async function discoverGa4Properties(
  accessToken: string,
): Promise<Ga4Resource[]> {
  const resources: Ga4Resource[] = [];
  let pageToken = "";

  do {
    const url = new URL("https://analyticsadmin.googleapis.com/v1alpha/accountSummaries");
    url.searchParams.set("pageSize", "200");
    if (pageToken) url.searchParams.set("pageToken", pageToken);
    const body = await googleJson<{
      accountSummaries?: Array<{
        name?: string;
        displayName?: string;
        propertySummaries?: Array<{ property?: string; displayName?: string }>;
      }>;
      nextPageToken?: string;
    }>(url, accessToken, {}, {}, {
      apiName: "Google Analytics Admin API",
      resource: "the authorized Google account",
    });

    for (const account of body.accountSummaries ?? []) {
      const accountId = suffix(account.name);
      for (const property of account.propertySummaries ?? []) {
        const propertyId = suffix(property.property);
        if (!propertyId) continue;
        resources.push({
          id: propertyId,
          name: property.displayName?.trim() || propertyId,
          property_id: propertyId,
          account_id: accountId,
          account_name: account.displayName?.trim() || accountId,
        });
      }
    }
    pageToken = body.nextPageToken ?? "";
  } while (pageToken);

  return resources.sort((a, b) => a.name.localeCompare(b.name));
}

export async function fetchGa4DailyMetrics(
  accessToken: string,
  propertyId: string,
  from: string,
  to: string,
): Promise<Ga4Metric[]> {
  const rows: Ga4Metric[] = [];
  const limit = 100_000;
  let offset = 0;
  let rowCount = 0;

  do {
    const body = await googleJson<{
      rows?: Record<string, unknown>[];
      rowCount?: number;
    }>(
      `https://analyticsdata.googleapis.com/v1beta/properties/${encodeURIComponent(suffix(propertyId))}:runReport`,
      accessToken,
      {
        method: "POST",
        body: JSON.stringify({
          dateRanges: [{ startDate: from, endDate: to }],
          dimensions: [{ name: "date" }],
          metrics: [
            { name: "totalUsers" },
            { name: "sessions" },
            { name: "newUsers" },
            { name: "engagedSessions" },
          ],
          orderBys: [{ dimension: { dimensionName: "date" } }],
          offset: String(offset),
          limit: String(limit),
          keepEmptyRows: false,
        }),
      },
      {},
      {
        apiName: "Google Analytics Data API",
        resource: `property ${suffix(propertyId)}`,
      },
    );
    const sourceRows = body.rows ?? [];
    rows.push(...sourceRows
      .map(normalizeGa4Row)
      .filter((row): row is Ga4Metric => row !== null));
    rowCount = Number(body.rowCount ?? sourceRows.length);
    offset += sourceRows.length;
  } while (offset < rowCount);

  return rows;
}

function suffix(value?: string) {
  return value?.split("/").at(-1)?.trim() ?? "";
}

import "server-only";

import { googleAdsHeaders, googleJson } from "../google/client";
import {
  normalizeGoogleAdsInsight,
  normalizeGoogleAdsResource,
  normalizeGoogleCustomerId,
  type GoogleAdsInsight,
  type GoogleAdsResource,
} from "../google/core";

const GOOGLE_ADS_API_VERSION = "v25";
const GOOGLE_ADS_ROOT =
  `https://googleads.googleapis.com/${GOOGLE_ADS_API_VERSION}`;

export async function discoverGoogleAdsCustomers(
  accessToken: string,
): Promise<GoogleAdsResource[]> {
  const accessible = await googleJson<{ resourceNames?: string[] }>(
    `${GOOGLE_ADS_ROOT}/customers:listAccessibleCustomers`,
    accessToken,
    {},
    googleAdsHeaders(),
    {
      apiName: "Google Ads API",
      resource: "the authorized Google account",
    },
  );
  const directIds = (accessible.resourceNames ?? [])
    .map(name => normalizeGoogleCustomerId(name))
    .filter(Boolean);
  const resources = new Map<string, GoogleAdsResource>();
  const managers: string[] = [];

  for (const customerId of directIds) {
    const rows = await googleAdsSearch(
      accessToken,
      customerId,
      [
        "SELECT customer.id, customer.descriptive_name,",
        "customer.currency_code, customer.time_zone, customer.manager",
        "FROM customer LIMIT 1",
      ].join(" "),
    );
    const customer = record(rows[0]?.customer);
    const resource = normalizeGoogleAdsResource({
      id: customer.id,
      descriptiveName: customer.descriptiveName,
      currencyCode: customer.currencyCode,
      timeZone: customer.timeZone,
    });

    if (customer.manager === true) managers.push(customerId);
    else if (resource) resources.set(resource.id, resource);
  }

  for (const managerId of managers) {
    const rows = await googleAdsSearch(
      accessToken,
      managerId,
      [
        "SELECT customer_client.id, customer_client.descriptive_name,",
        "customer_client.currency_code, customer_client.time_zone,",
        "customer_client.manager, customer_client.level,",
        "customer_client.status, customer_client.hidden",
        "FROM customer_client",
        "WHERE customer_client.status = 'ENABLED'",
      ].join(" "),
      managerId,
    );

    for (const row of rows) {
      const client = record(row.customerClient);
      if (client.manager === true || client.hidden === true || Number(client.level) === 0) continue;
      const resource = normalizeGoogleAdsResource({
        id: client.id,
        descriptiveName: client.descriptiveName,
        currencyCode: client.currencyCode,
        timeZone: client.timeZone,
      }, managerId);
      if (resource && !resources.has(resource.id)) resources.set(resource.id, resource);
    }
  }

  return [...resources.values()].sort((a, b) => a.name.localeCompare(b.name));
}

export async function fetchGoogleAdsDailyInsights(
  accessToken: string,
  customerId: string,
  loginCustomerId: string | undefined,
  from: string,
  to: string,
): Promise<GoogleAdsInsight[]> {
  const rows = await googleAdsSearch(
    accessToken,
    normalizeGoogleCustomerId(customerId),
    [
      "SELECT segments.date, customer.id, campaign.id, campaign.name,",
      "ad_group.id, ad_group.name, ad_group_ad.ad.id, ad_group_ad.ad.name,",
      "metrics.cost_micros, metrics.impressions, metrics.clicks, metrics.conversions",
      "FROM ad_group_ad",
      `WHERE segments.date BETWEEN '${from}' AND '${to}'`,
    ].join(" "),
    loginCustomerId,
  );

  return rows
    .map(normalizeGoogleAdsInsight)
    .filter((row): row is GoogleAdsInsight => row !== null);
}

async function googleAdsSearch(
  accessToken: string,
  customerId: string,
  query: string,
  loginCustomerId?: string,
) {
  const chunks = await googleJson<{ results?: Record<string, unknown>[] }[]>(
    `${GOOGLE_ADS_ROOT}/customers/${normalizeGoogleCustomerId(customerId)}/googleAds:searchStream`,
    accessToken,
    { method: "POST", body: JSON.stringify({ query }) },
    googleAdsHeaders(loginCustomerId),
    {
      apiName: "Google Ads API",
      resource: loginCustomerId
        ? `customer ${normalizeGoogleCustomerId(customerId)} via login customer ${normalizeGoogleCustomerId(loginCustomerId)}`
        : `customer ${normalizeGoogleCustomerId(customerId)}`,
    },
  );
  return chunks.flatMap(chunk => chunk.results ?? []);
}

function record(value: unknown): Record<string, unknown> {
  return Boolean(value) && typeof value === "object"
    ? value as Record<string, unknown>
    : {};
}

import "server-only";

import { googleJson } from "../google/client";
import { normalizeGbpTimeSeries, type GbpMetric } from "../google/core";

export type GoogleBusinessResource = {
  id: string;
  name: string;
  account_id: string;
  account_name: string;
  location_id: string;
  location_name: string;
};

const DAILY_METRICS = [
  "BUSINESS_IMPRESSIONS_DESKTOP_MAPS",
  "BUSINESS_IMPRESSIONS_MOBILE_MAPS",
  "BUSINESS_IMPRESSIONS_DESKTOP_SEARCH",
  "BUSINESS_IMPRESSIONS_MOBILE_SEARCH",
  "WEBSITE_CLICKS",
  "CALL_CLICKS",
  "BUSINESS_DIRECTION_REQUESTS",
];

export async function discoverGoogleBusinessLocations(
  accessToken: string,
): Promise<GoogleBusinessResource[]> {
  const accounts = await listAccounts(accessToken);
  const resources: GoogleBusinessResource[] = [];

  for (const account of accounts) {
    const accountId = suffix(account.name);
    if (!accountId) continue;
    let pageToken = "";

    do {
      const url = new URL(
        `https://mybusinessbusinessinformation.googleapis.com/v1/accounts/${encodeURIComponent(accountId)}/locations`,
      );
      url.searchParams.set("readMask", "name,title,storeCode,metadata");
      url.searchParams.set("pageSize", "100");
      if (pageToken) url.searchParams.set("pageToken", pageToken);
      const body = await googleJson<{
        locations?: Array<{ name?: string; title?: string; storeCode?: string }>;
        nextPageToken?: string;
      }>(url, accessToken, {}, {}, gbpContext(
        "Google Business Profile Business Information API",
        `account ${accountId}`,
      ));

      for (const location of body.locations ?? []) {
        const locationId = suffix(location.name);
        if (!locationId) continue;
        const locationName = location.title?.trim() || location.storeCode?.trim() || locationId;
        resources.push({
          id: locationId,
          name: locationName,
          account_id: accountId,
          account_name: account.accountName?.trim() || accountId,
          location_id: locationId,
          location_name: locationName,
        });
      }
      pageToken = body.nextPageToken ?? "";
    } while (pageToken);
  }

  return resources.sort((a, b) => a.name.localeCompare(b.name));
}

export async function fetchGoogleBusinessDailyMetrics(
  accessToken: string,
  locationId: string,
  from: string,
  to: string,
): Promise<GbpMetric[]> {
  const url = new URL(
    `https://businessprofileperformance.googleapis.com/v1/locations/${encodeURIComponent(suffix(locationId))}:fetchMultiDailyMetricsTimeSeries`,
  );
  for (const metric of DAILY_METRICS) url.searchParams.append("dailyMetrics", metric);
  addDate(url, "dailyRange.start_date", from);
  addDate(url, "dailyRange.end_date", to);
  const body = await googleJson<{
    multiDailyMetricTimeSeries?: Array<{
      dailyMetricTimeSeries?: Record<string, unknown>[];
    }>;
  }>(url, accessToken, {}, {}, gbpContext(
    "Google Business Profile Performance API",
    `location ${suffix(locationId)}`,
  ));

  return normalizeGbpTimeSeries(
    (body.multiDailyMetricTimeSeries ?? [])
      .flatMap(series => series.dailyMetricTimeSeries ?? []),
  );
}

async function listAccounts(accessToken: string) {
  const accounts: Array<{ name?: string; accountName?: string }> = [];
  let pageToken = "";
  do {
    const url = new URL("https://mybusinessaccountmanagement.googleapis.com/v1/accounts");
    url.searchParams.set("pageSize", "20");
    if (pageToken) url.searchParams.set("pageToken", pageToken);
    const body = await googleJson<{
      accounts?: Array<{ name?: string; accountName?: string }>;
      nextPageToken?: string;
    }>(url, accessToken, {}, {}, gbpContext(
      "Google Business Profile Account Management API",
      "the authorized Google account",
    ));
    accounts.push(...(body.accounts ?? []));
    pageToken = body.nextPageToken ?? "";
  } while (pageToken);
  return accounts;
}

function addDate(url: URL, prefix: string, value: string) {
  const [year, month, day] = value.split("-");
  url.searchParams.set(`${prefix}.year`, year);
  url.searchParams.set(`${prefix}.month`, month);
  url.searchParams.set(`${prefix}.day`, day);
}

function suffix(value?: string) {
  return value?.split("/").at(-1)?.trim() ?? "";
}

function gbpContext(apiName: string, resource: string) {
  return {
    apiName,
    resource,
    retryQuota: true,
    quotaHelp: "If this Cloud project has zero GBP API quota, submit Google's Application for Basic API Access; code cannot enable zero quota.",
  };
}

import "server-only";

import { createSupabaseAdminClient } from "@/lib/supabase/admin";
import { fetchGa4DailyMetrics } from "./ga4";
import { fetchGoogleAdsDailyInsights } from "./google-ads";
import { fetchGoogleBusinessDailyMetrics } from "./google-business";
import { getGoogleCredential, type GoogleProvider } from "./google/client";
import { googleAdsFactIdentity, googleAdsReplacementScope, normalizeGoogleCustomerId, searchConsolePersistenceRow, searchConsoleReplacementCompanyId, searchConsoleSyncIdentity, searchConsoleSyncScope } from "./google/core";
import { fetchSearchConsoleMetrics } from "./search-console";
import type { ConnectionConfiguration } from "./types";

const INITIAL_SYNC_FROM = "2026-01-01";

export type GoogleSyncResult = {
  provider: GoogleProvider;
  recordsImported: number;
  dailyRowsImported: number;
  dateFrom: string;
  dateTo: string;
  selectedResourceId: string;
  campaignsImported?: number;
  adGroupsImported?: number;
  adsImported?: number;
  totalSpend?: number;
};

export async function syncGoogleProvider(
  provider: GoogleProvider,
  connectionId: string,
  companyId: string,
  configuration: ConnectionConfiguration,
): Promise<GoogleSyncResult> {
  const credential = await getGoogleCredential(connectionId, provider);
  const dateTo = brusselsDate(new Date());

  if (provider === "google_ads") {
    return syncGoogleAds(
      credential.accessToken,
      companyId,
      configuration,
      dateTo,
    );
  }
  if (provider === "ga4") {
    return syncGa4(credential.accessToken, companyId, configuration, dateTo);
  }
  if (provider === "search_console") {
    return syncSearchConsole(
      credential.accessToken,
      companyId,
      configuration,
      dateTo,
    );
  }
  return syncGoogleBusiness(
    credential.accessToken,
    companyId,
    configuration,
    dateTo,
  );
}

async function syncGoogleAds(
  accessToken: string,
  companyId: string,
  configuration: ConnectionConfiguration,
  dateTo: string,
): Promise<GoogleSyncResult> {
  const customerId = normalizeGoogleCustomerId(configuration.customer_id);
  if (!customerId) throw new Error("Select a Google Ads customer before syncing.");
  const insights = await fetchGoogleAdsDailyInsights(
    accessToken,
    customerId,
    configuration.login_customer_id,
    INITIAL_SYNC_FROM,
    dateTo,
  );
  const admin = createSupabaseAdminClient();
  const company = await admin
    .from("companies")
    .select("organization_id")
    .eq("id", companyId)
    .single();
  if (company.error) throw new Error(`Unable to load the reporting company: ${company.error.message}`);

  const channel = await admin
    .from("marketing_channels")
    .upsert({
      organization_id: company.data.organization_id,
      name: "Google Ads",
      channel_type: "paid_search",
      is_paid: true,
    }, { onConflict: "organization_id,name" })
    .select("id")
    .single();
  if (channel.error) throw new Error(`Unable to prepare the Google Ads channel: ${channel.error.message}`);
  const channelId = String(channel.data.id);

  const campaigns = uniqueBy(insights, row => row.campaignId);
  const campaignRows = await upsertEntities(
    admin,
    "campaigns",
    campaigns.map(row => ({
      company_id: companyId,
      channel_id: channelId,
      external_id: row.campaignId,
      name: row.campaignName,
    })),
    "company_id,channel_id,external_id",
  );
  const campaignIds = new Map(campaignRows.map(row => [String(row.external_id), String(row.id)]));

  const adGroups = uniqueBy(insights, row => row.adGroupId);
  const adGroupRows = await upsertEntities(
    admin,
    "ad_groups",
    adGroups.map(row => ({
      campaign_id: requiredMap(campaignIds, row.campaignId, "campaign"),
      external_id: row.adGroupId,
      name: row.adGroupName,
      group_type: "ad_group",
    })),
    "campaign_id,external_id",
  );
  const adGroupIds = new Map(adGroupRows.map(row => [String(row.external_id), String(row.id)]));

  const ads = uniqueBy(insights, row => row.adId);
  const adRows = await upsertEntities(
    admin,
    "ads",
    ads.map(row => ({
      ad_group_id: requiredMap(adGroupIds, row.adGroupId, "ad group"),
      external_id: row.adId,
      name: row.adName,
    })),
    "ad_group_id,external_id",
  );
  const adIds = new Map(adRows.map(row => [String(row.external_id), String(row.id)]));

  // One Google Ads connection selects one customer. Replacing every Google Ads
  // fact in the window prevents an earlier customer selection from being mixed
  // with the currently selected account while leaving every other channel intact.
  const replacementScope = googleAdsReplacementScope(companyId, channelId);
  const removed = await admin
    .from("daily_marketing_metrics")
    .delete()
    .eq("company_id", replacementScope.companyId)
    .eq("channel_id", replacementScope.channelId)
    .gte("date", INITIAL_SYNC_FROM)
    .lte("date", dateTo);
  if (removed.error) throw new Error(`Unable to replace Google Ads daily facts: ${removed.error.message}`);

  await upsertChunks(
    admin,
    "daily_marketing_metrics",
    insights.map(row => {
      const identity = googleAdsFactIdentity(companyId, customerId, row);
      return {
        company_id: identity.companyId,
        date: identity.date,
        ad_account_id: identity.adAccountId,
        channel_id: channelId,
        campaign_id: requiredMap(campaignIds, identity.campaignExternalId, "campaign"),
        ad_group_id: requiredMap(adGroupIds, identity.adGroupExternalId, "ad group"),
        ad_id: requiredMap(adIds, identity.adExternalId, "ad"),
        service_id: null,
        spend: row.spend,
        impressions: row.impressions,
        reach: 0,
        clicks: row.clicks,
        landing_page_views: 0,
        platform_conversions: row.conversions,
      };
    }),
    "company_id,date,ad_account_id,channel_id,campaign_id,ad_group_id,ad_id,service_id",
  );

  return {
    provider: "google_ads",
    recordsImported: insights.length,
    dailyRowsImported: insights.length,
    campaignsImported: campaigns.length,
    adGroupsImported: adGroups.length,
    adsImported: ads.length,
    totalSpend: insights.reduce((sum, row) => sum + row.spend, 0),
    dateFrom: INITIAL_SYNC_FROM,
    dateTo,
    selectedResourceId: customerId,
  };
}

async function syncGa4(
  accessToken: string,
  companyId: string,
  configuration: ConnectionConfiguration,
  dateTo: string,
): Promise<GoogleSyncResult> {
  const propertyId = clean(configuration.property_id);
  if (!propertyId) throw new Error("Select a GA4 property before syncing.");
  const metrics = await fetchGa4DailyMetrics(
    accessToken,
    propertyId,
    INITIAL_SYNC_FROM,
    dateTo,
  );
  const admin = createSupabaseAdminClient();
  await replaceCompanyWindow(admin, "website_metrics", companyId, dateTo);
  await upsertChunks(
    admin,
    "website_metrics",
    metrics.map(row => ({
      company_id: companyId,
      date: row.date,
      landing_page: null,
      source: null,
      medium: null,
      device_category: null,
      users: row.users,
      sessions: row.sessions,
      new_users: row.newUsers,
      engaged_sessions: row.engagedSessions,
      form_submissions: row.formSubmissions,
      whatsapp_clicks: row.whatsappClicks,
      phone_clicks: row.phoneClicks,
      quote_requests: row.quoteRequests,
    })),
    "date,company_id,landing_page,source,medium,device_category",
  );
  return baseResult("ga4", metrics.length, propertyId, dateTo);
}

async function syncSearchConsole(
  accessToken: string,
  companyId: string,
  configuration: ConnectionConfiguration,
  dateTo: string,
): Promise<GoogleSyncResult> {
  const scope = searchConsoleSyncScope(companyId, configuration.site_url);
  const identity = searchConsoleSyncIdentity(scope);
  const metrics = await fetchSearchConsoleMetrics(
    accessToken,
    identity.requestSiteUrl,
    INITIAL_SYNC_FROM,
    dateTo,
  );
  const admin = createSupabaseAdminClient();
  await replaceCompanyWindow(
    admin,
    "seo_metrics",
    searchConsoleReplacementCompanyId(scope),
    dateTo,
  );
  await upsertChunks(
    admin,
    "seo_metrics",
    metrics.map(row => searchConsolePersistenceRow(scope, row)),
    "date,company_id,query,page",
  );
  return baseResult("search_console", metrics.length, identity.selectedResourceId, dateTo);
}

async function syncGoogleBusiness(
  accessToken: string,
  companyId: string,
  configuration: ConnectionConfiguration,
  dateTo: string,
): Promise<GoogleSyncResult> {
  const locationId = clean(configuration.location_id);
  if (!locationId) throw new Error("Select a Google Business Profile location before syncing.");
  const metrics = await fetchGoogleBusinessDailyMetrics(
    accessToken,
    locationId,
    INITIAL_SYNC_FROM,
    dateTo,
  );
  const admin = createSupabaseAdminClient();
  await replaceCompanyWindow(admin, "gbp_metrics", companyId, dateTo);
  await upsertChunks(
    admin,
    "gbp_metrics",
    metrics.map(row => ({
      company_id: companyId,
      date: row.date,
      profile_views: row.profileViews,
      website_clicks: row.websiteClicks,
      calls: row.calls,
      direction_requests: row.directionRequests,
      messages: 0,
      searches: 0,
      reviews: 0,
      rating_sum: 0,
    })),
    "date,company_id",
  );
  return baseResult("google_business", metrics.length, locationId, dateTo);
}

type Admin = ReturnType<typeof createSupabaseAdminClient>;
type EntityRow = { id: unknown; external_id: unknown };
type Table =
  | "daily_marketing_metrics"
  | "website_metrics"
  | "seo_metrics"
  | "gbp_metrics";

async function replaceCompanyWindow(
  admin: Admin,
  table: Exclude<Table, "daily_marketing_metrics">,
  companyId: string,
  dateTo: string,
) {
  const result = await admin
    .from(table)
    .delete()
    .eq("company_id", companyId)
    .gte("date", INITIAL_SYNC_FROM)
    .lte("date", dateTo);
  if (result.error) throw new Error(`Unable to replace ${table}: ${result.error.message}`);
}

async function upsertEntities(
  admin: Admin,
  table: "campaigns" | "ad_groups" | "ads",
  rows: Record<string, unknown>[],
  onConflict: string,
) {
  if (!rows.length) return [] as EntityRow[];
  const result = await admin.from(table).upsert(rows, { onConflict }).select("id,external_id");
  if (result.error) throw new Error(`Unable to upsert Google Ads ${table}: ${result.error.message}`);
  return (result.data ?? []) as unknown as EntityRow[];
}

async function upsertChunks(
  admin: Admin,
  table: Table,
  rows: Record<string, unknown>[],
  onConflict: string,
) {
  for (let index = 0; index < rows.length; index += 500) {
    const result = await admin
      .from(table)
      .upsert(rows.slice(index, index + 500), { onConflict });
    if (result.error) throw new Error(`Unable to upsert ${table}: ${result.error.message}`);
  }
}

function baseResult(
  provider: GoogleProvider,
  count: number,
  selectedResourceId: string,
  dateTo: string,
): GoogleSyncResult {
  return {
    provider,
    recordsImported: count,
    dailyRowsImported: count,
    dateFrom: INITIAL_SYNC_FROM,
    dateTo,
    selectedResourceId,
  };
}

function uniqueBy<T>(rows: T[], key: (row: T) => string) {
  return [...new Map(rows.map(row => [key(row), row])).values()];
}

function requiredMap(map: Map<string, string>, key: string, label: string) {
  const value = map.get(key);
  if (!value) throw new Error(`Google Ads ${label} ${key} could not be mapped to reporting storage.`);
  return value;
}

function clean(value?: string) {
  return value?.trim() ?? "";
}

function brusselsDate(date: Date) {
  const parts = new Intl.DateTimeFormat("en-CA", {
    timeZone: "Europe/Brussels",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(date);
  const value = Object.fromEntries(parts.map(part => [part.type, part.value]));
  return `${value.year}-${value.month}-${value.day}`;
}

export type GoogleAppConfig = {
  clientId: string;
  clientSecret: string;
  projectId: string;
};

export function parseGoogleAppConfig(value: unknown): GoogleAppConfig {
  let parsed: unknown = value;

  if (typeof value === "string") {
    try {
      parsed = JSON.parse(value);
    } catch {
      throw new Error("Google application configuration is invalid.");
    }
  }

  if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
    throw new Error("Google application configuration is invalid.");
  }

  const record = parsed as Record<string, unknown>;
  const config = {
    clientId: requiredString(record.clientId),
    clientSecret: requiredString(record.clientSecret),
    projectId: requiredString(record.projectId),
  };

  if (Object.values(config).some(value => !value)) {
    throw new Error("Google application configuration is incomplete.");
  }

  return config;
}

function requiredString(value: unknown) {
  return typeof value === "string" ? value.trim() : "";
}

import "server-only";

import { createSupabaseAdminClient } from "@/lib/supabase/admin";
import {
  parseGoogleAppConfig,
  type GoogleAppConfig,
} from "./app-config-core";

const GOOGLE_APP_CONFIG_KEY = "google";

export async function getGoogleAppConfig(): Promise<GoogleAppConfig> {
  const payload = await readGoogleAppConfigPayload();

  if (!payload) {
    throw new Error("Google application configuration is not set in Supabase Vault.");
  }

  return parseGoogleAppConfig(payload);
}

export async function isGoogleAppConfigured() {
  try {
    await getGoogleAppConfig();
    return true;
  } catch {
    return false;
  }
}

export async function putGoogleAppConfig(config: GoogleAppConfig): Promise<void> {
  const validated = parseGoogleAppConfig(config);
  const supabase = createSupabaseAdminClient();
  const { error } = await supabase.rpc(
    "reporting_put_app_integration_secret",
    {
      p_integration_key: GOOGLE_APP_CONFIG_KEY,
      p_secret: JSON.stringify(validated),
    },
  );

  if (error) {
    throw new Error(`Unable to store Google application configuration: ${error.message}`);
  }
}

async function readGoogleAppConfigPayload(): Promise<string | null> {
  const supabase = createSupabaseAdminClient();
  const { data, error } = await supabase.rpc(
    "reporting_get_app_integration_secret",
    { p_integration_key: GOOGLE_APP_CONFIG_KEY },
  );

  if (error) {
    throw new Error(`Unable to read Google application configuration: ${error.message}`);
  }

  return typeof data === "string" && data.trim() ? data : null;
}

