function isoParts(value: Record<string, unknown>) {
  const year = number(value.year);
  const month = number(value.month);
  const day = number(value.day);
  if (!year || !month || !day) return "";
  return `${String(year).padStart(4, "0")}-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
}

function googleError(body: Record<string, unknown>, status: number) {
  const error = record(body.error);
  return text(error.message) || text(body.error_description) || `HTTP ${status}`;
}

function values(value: unknown): Record<string, unknown>[] {
  return Array.isArray(value)
    ? value.filter(item => Boolean(item) && typeof item === "object") as Record<string, unknown>[]
    : [];
}

function record(value: unknown): Record<string, unknown> {
  return Boolean(value) && typeof value === "object"
    ? value as Record<string, unknown>
    : {};
}

function text(value: unknown) {
  return typeof value === "string" ? value.trim() : value === undefined || value === null ? "" : String(value);
}

function nullableText(value: unknown) {
  return text(value) || null;
}

function number(value: unknown) {
  const result = Number(value ?? 0);
  return Number.isFinite(result) ? result : 0;
}

function nonNegative(value: unknown) {
  return Math.max(0, number(value));
}

export type GoogleApiContext = {
  apiName: string;
  resource?: string;
  retryQuota?: boolean;
  quotaHelp?: string;
};

type GoogleJsonRequest = {
  request?: RequestInit;
  headers?: Record<string, string>;
  context: GoogleApiContext;
  fetchImpl?: typeof fetch;
  sleep?: (milliseconds: number) => Promise<void>;
  random?: () => number;
  maxRetries?: number;
};

export async function requestGoogleJson<T>(
  url: string | URL,
  accessToken: string,
  options: GoogleJsonRequest,
): Promise<T> {
  const fetchImpl = options.fetchImpl ?? fetch;
  const sleep = options.sleep ?? (milliseconds => new Promise(resolve => setTimeout(resolve, milliseconds)));
  const random = options.random ?? Math.random;
  const maxRetries = options.maxRetries ?? 3;

  for (let attempt = 0; attempt <= maxRetries; attempt += 1) {
    const response = await fetchImpl(url, {
      ...options.request,
      headers: {
        Authorization: `Bearer ${accessToken}`,
        ...(options.request?.body ? { "Content-Type": "application/json" } : {}),
        ...options.headers,
        ...(options.request?.headers ?? {}),
      },
      cache: "no-store",
    });
    const body = await response.json().catch(() => ({})) as Record<string, unknown>;
    if (response.ok) return body as T;

    const parsed = parseGoogleApiError(
      response.status,
      body,
      options.context,
      response.headers.get("request-id") ?? response.headers.get("x-request-id"),
    );
    const quotaFailure = response.status === 429 || parsed.canonicalStatus === "RESOURCE_EXHAUSTED";
    if (!options.context.retryQuota || !quotaFailure || attempt === maxRetries) {
      throw new Error(formatGoogleApiError(parsed, options.context, quotaFailure && attempt === maxRetries, maxRetries));
    }

    await sleep(retryDelayMilliseconds(response.headers.get("retry-after"), attempt, random));
  }

  throw new Error(`${options.context.apiName} failed after quota retries.`);
}

export function parseGoogleApiError(
  httpStatus: number,
  body: Record<string, unknown>,
  context: GoogleApiContext,
  headerRequestId: string | null = null,
) {
  const error = record(body.error);
  const canonicalStatus = text(error.status);
  const message = text(error.message) || `Request failed for ${context.resource ?? "the selected resource"}.`;
  const nested = nestedGoogleFailure(error.details);
  return {
    httpStatus,
    canonicalStatus,
    message,
    nestedCode: nested.code,
    nestedMessage: nested.message,
    requestId: nested.requestId || text(headerRequestId),
  };
}

export function retryDelayMilliseconds(
  retryAfter: string | null,
  retryIndex: number,
  random: () => number = Math.random,
) {
  const seconds = Number(retryAfter);
  if (retryAfter && Number.isFinite(seconds) && seconds >= 0) return seconds * 1000;
  if (retryAfter) {
    const absolute = Date.parse(retryAfter);
    if (Number.isFinite(absolute)) return Math.max(0, absolute - Date.now());
  }
  const base = 500 * 2 ** retryIndex;
  return base + Math.floor(random() * base);
}

function formatGoogleApiError(
  error: ReturnType<typeof parseGoogleApiError>,
  context: GoogleApiContext,
  exhausted: boolean,
  maxRetries: number,
) {
  const status = [String(error.httpStatus), error.canonicalStatus].filter(Boolean).join(" ");
  const resource = context.resource ? ` [${context.resource}]` : "";
  const nested = error.nestedCode
    ? ` ${error.nestedCode}${error.nestedMessage ? ` — ${error.nestedMessage.replace(/[.\s]+$/, "")}` : ""}.`
    : "";
  const requestId = error.requestId ? ` request-id=${error.requestId}.` : "";
  const suffix = exhausted
    ? ` Quota remained exhausted after ${maxRetries} retries.${context.quotaHelp ? ` ${context.quotaHelp}` : ""}`
    : "";
  return `${context.apiName} failed: HTTP ${status} — ${error.message.replace(/[.\s]+$/, "")}${resource}.${nested}${requestId}${suffix}`;
}

function nestedGoogleFailure(value: unknown) {
  if (!Array.isArray(value)) return { code: "", message: "", requestId: "" };

  for (const detailValue of value) {
    const detail = record(detailValue);
    const requestId = text(detail.requestId);
    const errors = Array.isArray(detail.errors) ? detail.errors : [];

    for (const errorValue of errors) {
      const nestedError = record(errorValue);
      const errorCode = record(nestedError.errorCode);
      const codeEntry = Object.entries(errorCode)
        .find(([, code]) => typeof code === "string" && code.trim());
      if (codeEntry) {
        return {
          code: `${codeEntry[0]}.${String(codeEntry[1]).trim()}`,
          message: text(nestedError.message),
          requestId,
        };
      }
    }

    if (requestId) return { code: "", message: "", requestId };
  }

  return { code: "", message: "", requestId: "" };
}

function record(value: unknown): Record<string, unknown> {
  return value && typeof value === "object" && !Array.isArray(value)
    ? value as Record<string, unknown>
    : {};
}

function text(value: unknown) {
  return typeof value === "string" ? value.trim() : "";
}

import "server-only";

import { discoverGa4Properties } from "../ga4";
import { discoverGoogleAdsCustomers } from "../google-ads";
import { discoverGoogleBusinessLocations } from "../google-business";
import { discoverSearchConsoleSites } from "../search-console";
import type { ConnectionConfiguration } from "../types";
import type { GoogleProvider } from "./client";

export type GoogleResource = {
  id: string;
  name: string;
  customer_id?: string;
  customer_name?: string;
  login_customer_id?: string;
  currency?: string | null;
  timezone?: string | null;
  property_id?: string;
  account_id?: string;
  account_name?: string;
  site_url?: string;
  location_id?: string;
  location_name?: string;
};

export async function discoverGoogleResources(
  provider: GoogleProvider,
  accessToken: string,
): Promise<GoogleResource[]> {
  if (provider === "google_ads") {
    return (await discoverGoogleAdsCustomers(accessToken)).map(resource => ({
      ...resource,
      customer_name: resource.name,
    }));
  }
  if (provider === "ga4") return discoverGa4Properties(accessToken);
  if (provider === "search_console") return discoverSearchConsoleSites(accessToken);
  return discoverGoogleBusinessLocations(accessToken);
}

export function googleResourceConfiguration(
  provider: GoogleProvider,
  resource: GoogleResource,
): ConnectionConfiguration {
  if (provider === "google_ads") {
    return compact({
      customer_id: resource.customer_id ?? resource.id,
      customer_name: resource.customer_name ?? resource.name,
      login_customer_id: resource.login_customer_id,
      currency: resource.currency ?? undefined,
      timezone: resource.timezone ?? undefined,
    });
  }
  if (provider === "ga4") {
    return compact({
      property_id: resource.property_id ?? resource.id,
      property_name: resource.name,
      account_id: resource.account_id,
      account_name: resource.account_name,
    });
  }
  if (provider === "search_console") {
    return { site_url: resource.site_url ?? resource.id };
  }
  return compact({
    account_id: resource.account_id,
    account_name: resource.account_name,
    location_id: resource.location_id ?? resource.id,
    location_name: resource.location_name ?? resource.name,
  });
}

function compact<T extends Record<string, string | undefined>>(value: T) {
  return Object.fromEntries(
    Object.entries(value).filter((entry): entry is [string, string] => Boolean(entry[1])),
  ) as ConnectionConfiguration;
}

