export async function syncMetaLeadAttribution(
  admin: Admin,
  companyId: string,
  records: MetaLeadRecord[],
  campaignIds: Map<string, string>,
  adGroupIds: Map<string, string>,
  adIds: Map<string, string>,
): Promise<MetaLeadSyncResult> {
  const crmResult = await admin
    .from("leads")
    .select("id,email,phone,meta_lead_id")
    .eq("company_id", companyId);
  if (crmResult.error) throw new Error(`Unable to load CRM leads for Meta attribution: ${crmResult.error.message}`);

  const crmLeads = ((crmResult.data ?? []) as CrmLeadRow[]).map(row => ({
    id: row.id,
    email: row.email,
    phone: row.phone,
    metaLeadId: row.meta_lead_id,
  }));
  const now = new Date().toISOString();
  const attributionRows: Record<string, unknown>[] = [];
  const leadUpdates: Array<{ leadId: string; values: Record<string, unknown> }> = [];

  for (const record of records) {
    const match = matchMetaLead(record, crmLeads);
    const mapping = entityMapping(record, campaignIds, adGroupIds, adIds);
    attributionRows.push({
      company_id: companyId,
      meta_lead_id: record.id,
      created_time: record.createdTime,
      page_id: record.pageId,
      form_id: record.formId,
      campaign_external_id: record.campaignExternalId,
      adset_external_id: record.adsetExternalId,
      ad_external_id: record.adExternalId,
      campaign_id: mapping.campaignId,
      ad_group_id: mapping.adGroupId,
      ad_id: mapping.adId,
      email_normalized: normalizeMetaEmail(record.email) || null,
      phone_normalized: normalizeMetaPhone(record.phone) || null,
      matched_lead_id: match.leadId,
      match_method: match.method,
      match_status: match.status,
      matched_at: match.status === "MATCHED" ? now : null,
      updated_at: now,
    });

    if (match.leadId) {
      leadUpdates.push({
        leadId: match.leadId,
        values: crmLeadAttributionUpdate(record.id, mapping),
      });
      const claimed = crmLeads.find(lead => lead.id === match.leadId);
      if (claimed) claimed.metaLeadId = record.id;
    }
  }

  for (let index = 0; index < attributionRows.length; index += 500) {
    const result = await admin
      .from("meta_lead_attribution")
      .upsert(attributionRows.slice(index, index + 500), {
        onConflict: "company_id,meta_lead_id",
      });
    if (result.error) throw new Error(`Unable to store Meta lead attribution: ${result.error.message}`);
  }

  for (let index = 0; index < leadUpdates.length; index += 25) {
    await Promise.all(leadUpdates.slice(index, index + 25).map(async update => {
      const result = await admin
        .from("leads")
        .update(update.values)
        .eq("id", update.leadId)
        .eq("company_id", companyId);
      if (result.error) throw new Error(`Unable to update attributed CRM lead: ${result.error.message}`);
    }));
  }

  const matched = attributionRows.filter(row => row.match_status === "MATCHED").length;
  const unmatched = attributionRows.filter(row => row.match_status === "UNMATCHED").length;
  const ambiguous = attributionRows.filter(row => row.match_status === "AMBIGUOUS").length;
  const dates = records.map(record => record.createdTime).filter(Boolean).sort();
  return {
    imported: records.length,
    matched,
    unmatched,
    ambiguous,
    earliest: dates[0] ?? null,
    latest: dates.at(-1) ?? null,
    matchRate: records.length ? matched / records.length : 0,
  };
}

import "server-only";

import { createSupabaseAdminClient } from "@/lib/supabase/admin";
import { credentialStore } from "./credentials";
import { syncMetaLeadAttribution, type MetaLeadSyncResult } from "./meta-lead-sync";
import { fetchMetaDailyInsights, fetchMetaLeadAds, fetchMetaPermissionState } from "./meta/client";
import { normalizeMetaAdAccountId, type MetaInsight } from "./meta/core";
import type { MetaLeadRecord } from "./meta/lead-attribution-core";
import { optionalMetaLeadPhase, parseMetaPermissionRows, readMetaSyncSources, type MetaReadinessStatus } from "./meta/production-core";
import type { ConnectionConfiguration } from "./types";

const INITIAL_SYNC_FROM = "2026-01-01";

export type MetaSyncResult = {
  recordsImported: number;
  dailyRowsImported: number;
  campaignsImported: number;
  adsetsImported: number;
  adsImported: number;
  dateFrom: string;
  dateTo: string;
  earliestDate: string | null;
  latestDate: string | null;
  totalSpend: number;
  selectedAdAccountId: string;
  monthlySpend: { month: string; spend: number; rowCount: number }[];
  missingMonths: string[];
  metaLeadsImported: number;
  metaLeadsMatched: number;
  metaLeadsUnmatched: number;
  metaLeadsAmbiguous: number;
  earliestMetaLead: string | null;
  latestMetaLead: string | null;
  metaLeadMatchRate: number;
  metaLeadAttributionWarning: string | null;
  metaPermissionStatus: MetaReadinessStatus;
  grantedPermissions: string[];
  missingPermissions: string[];
  leadAdsAvailable: boolean;
  metaLeadRetrievalScope: "direct_forms" | "selected_pages" | "accessible_pages_fallback" | null;
  metaLeadPagesProcessed: number;
  metaLeadFormsProcessed: number;
};

export async function syncMetaProvider(
  connectionId: string,
  companyId: string,
  configuration: ConnectionConfiguration,
): Promise<MetaSyncResult> {
  const adAccountId = normalizeMetaAdAccountId(configuration.ad_account_id ?? "");
  if (!adAccountId) {
    throw new Error("Select a Meta ad account before syncing.");
  }

  const credential = await credentialStore.read(connectionId, "meta");
  if (!credential?.accessToken) {
    throw new Error("Meta authorization is missing. Reconnect Meta and try again.");
  }

  const permissionCheck = await optionalMetaLeadPhase(
    () => fetchMetaPermissionState(credential.accessToken),
    "Meta permission verification is unavailable.",
  );
  const storedPermissionRows = Object.entries(credential.permissionStatuses ?? {}).map(
    ([permission, status]) => ({ permission, status }),
  );
  const permissions = permissionCheck.value ?? parseMetaPermissionRows(storedPermissionRows);
  const leadWarnings = permissionCheck.warning ? [permissionCheck.warning] : [];
  if (permissionCheck.value) {
    const credentialUpdate = await optionalMetaLeadPhase(
      () => credentialStore.write(connectionId, "meta", {
        ...credential,
        scopes: permissions.granted,
        permissionStatuses: permissions.statuses,
      }),
      "Verified Meta permissions could not be saved to secure credential storage.",
    );
    if (credentialUpdate.warning) leadWarnings.push(credentialUpdate.warning);
  }

  const dateTo = brusselsDate(new Date());
  const sources = await readMetaSyncSources({
    fetchInsights: () => fetchMetaDailyInsights(
      credential.accessToken,
      adAccountId,
      INITIAL_SYNC_FROM,
      dateTo,
    ),
    fetchLeads: () => fetchMetaLeadAds(credential.accessToken, adAccountId),
    leadAdsAvailable: permissions.leadAdsAvailable,
    unavailableWarning: `Lead Ads retrieval is unavailable because these Meta permissions are missing: ${permissions.missing.join(", ")}.`,
  });
  const insights = sources.insights;
  let metaLeads: MetaLeadRecord[] = [];
  let metaLeadRetrievalScope: MetaSyncResult["metaLeadRetrievalScope"] = null;
  let metaLeadPagesProcessed = 0;
  let metaLeadFormsProcessed = 0;
  if (sources.leads) {
    metaLeads = sources.leads.records;
    metaLeadRetrievalScope = sources.leads.retrievalScope;
    metaLeadPagesProcessed = sources.leads.pagesProcessed;
    metaLeadFormsProcessed = sources.leads.formsProcessed;
  }
  if (sources.warning) leadWarnings.push(sources.warning);
  const admin = createSupabaseAdminClient();
  const companyResult = await admin
    .from("companies")
    .select("organization_id")
    .eq("id", companyId)
    .single();
  if (companyResult.error) throw new Error(`Unable to load the reporting company: ${companyResult.error.message}`);

  const channelResult = await admin
    .from("marketing_channels")
    .upsert({
      organization_id: companyResult.data.organization_id,
      name: "Meta Ads",
      channel_type: "paid_social",
      is_paid: true,
    }, { onConflict: "organization_id,name" })
    .select("id")
    .single();
  if (channelResult.error) throw new Error(`Unable to prepare the Meta channel: ${channelResult.error.message}`);

  const channelId = channelResult.data.id;
  const campaignSources = [
    ...insights.map(row => ({ id: row.campaignId, name: row.campaignName })),
    ...metaLeads.flatMap(row => row.campaignExternalId
      ? [{ id: row.campaignExternalId, name: row.campaignName ?? row.campaignExternalId }]
      : []),
  ];
  const campaigns = uniqueBy(campaignSources, row => row.id);
  const campaignRows = await upsertEntities(
    admin,
    "campaigns",
    campaigns.map(row => ({
      company_id: companyId,
      channel_id: channelId,
      external_id: row.id,
      name: row.name,
    })),
    "company_id,channel_id,external_id",
  );
  const campaignIds = new Map(campaignRows.map(row => [String(row.external_id), String(row.id)]));

  const adsetSources = [
    ...insights.map(row => ({ id: row.adsetId, name: row.adsetName, campaignId: row.campaignId })),
    ...metaLeads.flatMap(row => row.adsetExternalId && row.campaignExternalId
      ? [{
          id: row.adsetExternalId,
          name: row.adsetName ?? row.adsetExternalId,
          campaignId: row.campaignExternalId,
        }]
      : []),
  ];
  const adsets = uniqueBy(adsetSources, row => row.id);
  const adsetRows = await upsertEntities(
    admin,
    "ad_groups",
    adsets.map(row => ({
      campaign_id: requiredMap(campaignIds, row.campaignId, "campaign"),
      external_id: row.id,
      name: row.name,
      group_type: "ad_set",
    })),
    "campaign_id,external_id",
  );
  const adsetIds = new Map(adsetRows.map(row => [String(row.external_id), String(row.id)]));

  const adSources = [
    ...insights.map(row => ({ id: row.adId, name: row.adName, adsetId: row.adsetId })),
    ...metaLeads.flatMap(row => row.adExternalId && row.adsetExternalId
      ? [{
          id: row.adExternalId,
          name: row.adName ?? row.adExternalId,
          adsetId: row.adsetExternalId,
        }]
      : []),
  ];
  const ads = uniqueBy(adSources, row => row.id);
  const adRows = await upsertEntities(
    admin,
    "ads",
    ads.map(row => ({
      ad_group_id: requiredMap(adsetIds, row.adsetId, "ad set"),
      external_id: row.id,
      name: row.name,
    })),
    "ad_group_id,external_id",
  );
  const adIds = new Map(adRows.map(row => [String(row.external_id), String(row.id)]));

  // Only replace rows after the complete Meta response has been received.
  // This keeps each selected account's reporting window exact and prevents
  // stale rows when Meta revises attribution or an ad-day disappears.
  const deleteResult = await admin
    .from("daily_marketing_metrics")
    .delete()
    .eq("company_id", companyId)
    .eq("channel_id", channelId)
    .eq("ad_account_id", adAccountId)
    .gte("date", INITIAL_SYNC_FROM)
    .lte("date", dateTo);
  if (deleteResult.error) throw new Error(`Unable to replace existing Meta daily facts: ${deleteResult.error.message}`);

  await upsertInChunks(
    admin,
    "daily_marketing_metrics",
    insights.map(row => ({
      company_id: companyId,
      date: row.date,
      ad_account_id: adAccountId,
      channel_id: channelId,
      campaign_id: requiredMap(campaignIds, row.campaignId, "campaign"),
      ad_group_id: requiredMap(adsetIds, row.adsetId, "ad set"),
      ad_id: requiredMap(adIds, row.adId, "ad"),
      service_id: null,
      spend: row.spend,
      impressions: row.impressions,
      reach: row.reach,
      clicks: row.clicks,
      landing_page_views: row.landingPageViews,
      platform_conversions: row.platformLeads,
    })),
    "company_id,date,ad_account_id,channel_id,campaign_id,ad_group_id,ad_id,service_id",
  );

  let leadSync = emptyMetaLeadSync();
  if (metaLeads.length) {
    const attribution = await optionalMetaLeadPhase(
      () => syncMetaLeadAttribution(
        admin,
        companyId,
        metaLeads,
        campaignIds,
        adsetIds,
        adIds,
      ),
      "Meta Lead Ads attribution could not be persisted.",
    );
    if (attribution.value) leadSync = attribution.value;
    if (attribution.warning) leadWarnings.push(attribution.warning);
  }

  const dates = insights.map(row => row.date).sort();
  const monthlySpend = monthlySummary(insights);
  return {
    recordsImported: insights.length + leadSync.imported,
    dailyRowsImported: insights.length,
    campaignsImported: campaigns.length,
    adsetsImported: adsets.length,
    adsImported: ads.length,
    dateFrom: INITIAL_SYNC_FROM,
    dateTo,
    earliestDate: dates[0] ?? null,
    latestDate: dates.at(-1) ?? null,
    totalSpend: insights.reduce((total, row) => total + row.spend, 0),
    selectedAdAccountId: adAccountId,
    monthlySpend,
    missingMonths: calendarMonths(INITIAL_SYNC_FROM, dateTo).filter(
      month => !monthlySpend.some(row => row.month === month),
    ),
    metaLeadsImported: leadSync.imported,
    metaLeadsMatched: leadSync.matched,
    metaLeadsUnmatched: leadSync.unmatched,
    metaLeadsAmbiguous: leadSync.ambiguous,
    earliestMetaLead: leadSync.earliest,
    latestMetaLead: leadSync.latest,
    metaLeadMatchRate: leadSync.matchRate,
    metaLeadAttributionWarning: leadWarnings.length ? leadWarnings.join(" ") : null,
    metaPermissionStatus: permissions.status,
    grantedPermissions: permissions.granted,
    missingPermissions: permissions.missing,
    leadAdsAvailable: permissions.leadAdsAvailable,
    metaLeadRetrievalScope,
    metaLeadPagesProcessed,
    metaLeadFormsProcessed,
  };
}

type Admin = ReturnType<typeof createSupabaseAdminClient>;
type EntityRow = { id: unknown; external_id: unknown };

async function upsertEntities(
  admin: Admin,
  table: "campaigns" | "ad_groups" | "ads",
  rows: Record<string, unknown>[],
  onConflict: string,
) {
  if (!rows.length) return [] as EntityRow[];
  const result = await admin.from(table).upsert(rows, { onConflict }).select("id,external_id");
  if (result.error) throw new Error(`Unable to upsert Meta ${table}: ${result.error.message}`);
  return (result.data ?? []) as unknown as EntityRow[];
}

async function upsertInChunks(
  admin: Admin,
  table: "daily_marketing_metrics",
  rows: Record<string, unknown>[],
  onConflict: string,
) {
  for (let index = 0; index < rows.length; index += 500) {
    const result = await admin.from(table).upsert(rows.slice(index, index + 500), { onConflict });
    if (result.error) throw new Error(`Unable to upsert Meta daily facts: ${result.error.message}`);
  }
}

function uniqueBy<T>(rows: T[], key: (row: T) => string) {
  return [...new Map(rows.map(row => [key(row), row])).values()];
}

function emptyMetaLeadSync(): MetaLeadSyncResult {
  return {
    imported: 0,
    matched: 0,
    unmatched: 0,
    ambiguous: 0,
    earliest: null,
    latest: null,
    matchRate: 0,
  };
}

function requiredMap(map: Map<string, string>, key: string, label: string) {
  const value = map.get(key);
  if (!value) throw new Error(`Meta ${label} ${key} could not be mapped to reporting storage.`);
  return value;
}

function monthlySummary(rows: MetaInsight[]) {
  const totals = new Map<string, { month: string; spend: number; rowCount: number }>();
  for (const row of rows) {
    const month = row.date.slice(0, 7);
    const current = totals.get(month) ?? { month, spend: 0, rowCount: 0 };
    current.spend += row.spend;
    current.rowCount += 1;
    totals.set(month, current);
  }
  return [...totals.values()].sort((a, b) => a.month.localeCompare(b.month));
}

function calendarMonths(from: string, to: string) {
  const months: string[] = [];
  const cursor = new Date(`${from.slice(0, 7)}-01T12:00:00Z`);
  const end = to.slice(0, 7);
  while (cursor.toISOString().slice(0, 7) <= end) {
    months.push(cursor.toISOString().slice(0, 7));
    cursor.setUTCMonth(cursor.getUTCMonth() + 1);
  }
  return months;
}

function brusselsDate(date: Date) {
  const parts = new Intl.DateTimeFormat("en-CA", {
    timeZone: "Europe/Brussels",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(date);
  const value = Object.fromEntries(parts.map(part => [part.type, part.value]));
  return `${value.year}-${value.month}-${value.day}`;
}

import "server-only";

import { deduplicateMetaLeads, type MetaLeadRecord } from "./lead-attribution-core";
import { normalizeMetaAdAccountId, normalizeMetaInsight, type MetaAdAccount, type MetaInsight } from "./core";
import {
  metaAdContext,
  parseMetaPermissionRows,
  selectedMetaLeadRecord,
  type MetaAdContext,
} from "./production-core";

const GRAPH_ROOT = "https://graph.facebook.com/v26.0";

export async function discoverMetaAdAccounts(accessToken: string): Promise<MetaAdAccount[]> {
  const url = new URL(`${GRAPH_ROOT}/me/adaccounts`);
  url.searchParams.set("fields", "id,name,account_id,currency,timezone_name");
  url.searchParams.set("limit", "200");

  const rows = await fetchAll(url, accessToken);
  return rows.map(row => ({
    id: normalizeMetaAdAccountId(stringValue(row.id) || stringValue(row.account_id)),
    name: stringValue(row.name) || "Unnamed Meta ad account",
    currency: nullableString(row.currency),
    timezone: nullableString(row.timezone_name),
  })).filter(account => account.id);
}

export async function fetchMetaPermissionState(accessToken: string) {
  const url = new URL(`${GRAPH_ROOT}/me/permissions`);
  url.searchParams.set("limit", "200");
  return parseMetaPermissionRows(await fetchAll(url, accessToken));
}

export async function fetchMetaDailyInsights(
  accessToken: string,
  adAccountId: string,
  from: string,
  to: string,
): Promise<MetaInsight[]> {
  const url = new URL(`${GRAPH_ROOT}/${normalizeMetaAdAccountId(adAccountId)}/insights`);
  url.searchParams.set("fields", [
    "date_start",
    "date_stop",
    "campaign_id",
    "campaign_name",
    "adset_id",
    "adset_name",
    "ad_id",
    "ad_name",
    "spend",
    "impressions",
    "reach",
    "clicks",
    "actions",
  ].join(","));
  url.searchParams.set("level", "ad");
  url.searchParams.set("time_increment", "1");
  url.searchParams.set("time_range", JSON.stringify({ since: from, until: to }));
  url.searchParams.set("limit", "500");

  const rows = await fetchAll(url, accessToken);
  return rows.map(normalizeMetaInsight).filter((row): row is MetaInsight => row !== null);
}

export async function fetchMetaLeadAds(
  accessToken: string,
  adAccountId: string,
): Promise<{
  records: MetaLeadRecord[];
  retrievalScope: "direct_forms" | "selected_pages" | "accessible_pages_fallback";
  pagesProcessed: number;
  formsProcessed: number;
}> {
  const adsUrl = new URL(`${GRAPH_ROOT}/${normalizeMetaAdAccountId(adAccountId)}/ads`);
  adsUrl.searchParams.set("fields", "id,name,campaign{id,name},adset{id,name},creative{object_story_spec}");
  adsUrl.searchParams.set("limit", "500");
  const adRows = await fetchAll(adsUrl, accessToken);
  const contexts = adRows
    .map(metaAdContext)
    .filter((row): row is MetaAdContext => row !== null);
  const ads = new Map(contexts.map(row => [row.id, row]));
  const relevantPageIds = new Set(contexts.flatMap(row => row.pageId ? [row.pageId] : []));
  const directForms = new Map<string, string | null>();
  for (const ad of contexts) {
    for (const formId of ad.formIds) directForms.set(formId, ad.pageId);
  }

  const pageRows = relevantPageIds.size || directForms.size === 0
    ? await fetchMetaPages(accessToken)
    : [];
  const candidatePages = relevantPageIds.size
    ? pageRows.filter(page => relevantPageIds.has(stringValue(page.id)))
    : directForms.size
      ? []
      : pageRows;
  const retrievalScope = directForms.size && candidatePages.length === 0
    ? "direct_forms" as const
    : relevantPageIds.size
      ? "selected_pages" as const
      : "accessible_pages_fallback" as const;
  const formTargets = new Map<string, { pageId: string | null; accessToken: string }>();

  for (const [formId, pageId] of directForms) {
    const page = pageRows.find(row => stringValue(row.id) === pageId);
    formTargets.set(formId, {
      pageId,
      accessToken: page ? stringValue(page.access_token) || accessToken : accessToken,
    });
  }

  for (const page of candidatePages) {
    const pageId = stringValue(page.id);
    const pageAccessToken = stringValue(page.access_token) || accessToken;
    if (!pageId) continue;
    const pageAds = contexts.filter(ad => ad.pageId === pageId);
    const pageDirectForms = pageAds.flatMap(ad => ad.formIds);
    if (pageDirectForms.length) {
      for (const formId of pageDirectForms) {
        formTargets.set(formId, { pageId, accessToken: pageAccessToken });
      }
      if (pageAds.every(ad => ad.formIds.length > 0)) continue;
    }

    // Meta does not consistently expose lead_gen_form_id on every historical
    // creative. In that case form discovery is restricted to the exact Page ID
    // declared by a selected-account ad. Only if no selected ad exposes any Page
    // or form identity do we fall back to accessible Pages, and every lead is
    // still filtered against the selected account's ad IDs before persistence.
    const formsUrl = new URL(`${GRAPH_ROOT}/${pageId}/leadgen_forms`);
    formsUrl.searchParams.set("fields", "id,name,status");
    formsUrl.searchParams.set("limit", "200");
    for (const form of await fetchAll(formsUrl, pageAccessToken)) {
      const formId = stringValue(form.id);
      if (formId) formTargets.set(formId, { pageId, accessToken: pageAccessToken });
    }
  }

  const records: MetaLeadRecord[] = [];

  for (const [formId, target] of formTargets) {
    const leadsUrl = new URL(`${GRAPH_ROOT}/${formId}/leads`);
    leadsUrl.searchParams.set("fields", [
      "id",
      "created_time",
      "ad_id",
      "ad_name",
      "adset_id",
      "adset_name",
      "campaign_id",
      "campaign_name",
      "form_id",
      "field_data",
    ].join(","));
    leadsUrl.searchParams.set("limit", "500");
    const leads = await fetchAll(leadsUrl, target.accessToken);

    for (const lead of leads) {
      const record = selectedMetaLeadRecord(lead, target.pageId, formId, ads);
      if (record?.createdTime) records.push(record);
    }
  }

  return {
    records: deduplicateMetaLeads(records),
    retrievalScope,
    pagesProcessed: candidatePages.length,
    formsProcessed: formTargets.size,
  };
}

async function fetchMetaPages(accessToken: string) {
  const pagesUrl = new URL(`${GRAPH_ROOT}/me/accounts`);
  pagesUrl.searchParams.set("fields", "id,name,access_token");
  pagesUrl.searchParams.set("limit", "200");
  return fetchAll(pagesUrl, accessToken);
}

async function fetchAll(initialUrl: URL, accessToken: string) {
  const rows: Record<string, unknown>[] = [];
  let next: string | null = initialUrl.toString();

  while (next) {
    const response = await fetch(next, {
      headers: { Authorization: `Bearer ${accessToken}` },
      cache: "no-store",
    });
    const body = await response.json().catch(() => ({})) as {
      data?: Record<string, unknown>[];
      paging?: { next?: string };
      error?: { message?: string; code?: number };
    };

    if (!response.ok) {
      const detail = body.error?.message ? ` ${body.error.message}` : "";
      throw new Error(`Meta Graph API request failed with HTTP ${response.status}.${detail}`);
    }

    rows.push(...(body.data ?? []));
    next = body.paging?.next ?? null;
  }

  return rows;
}

function stringValue(value: unknown) {
  return typeof value === "string" ? value.trim() : "";
}

function nullableString(value: unknown) {
  return stringValue(value) || null;
}

export type MetaAdAccount = {
  id: string;
  name: string;
  currency: string | null;
  timezone: string | null;
};

export type MetaInsight = {
  date: string;
  campaignId: string;
  campaignName: string;
  adsetId: string;
  adsetName: string;
  adId: string;
  adName: string;
  spend: number;
  impressions: number;
  reach: number;
  clicks: number;
  landingPageViews: number;
  platformLeads: number;
};

type MetaAction = { action_type?: unknown; value?: unknown };

export function normalizeMetaAdAccountId(value: string) {
  const trimmed = value.trim();
  if (!trimmed) return "";
  return trimmed.startsWith("act_") ? trimmed : `act_${trimmed}`;
}

export function platformLeadCount(actions: unknown) {
  const values = actionValues(actions);

  // Meta can return both an aggregate lead action and its components. Use one
  // clearly identified value in priority order so platform leads are not doubled.
  for (const type of [
    "lead",
    "onsite_conversion.lead_grouped",
    "onsite_conversion.lead",
    "offsite_conversion.fb_pixel_lead",
  ]) {
    if (values.has(type)) return values.get(type) ?? 0;
  }

  return 0;
}

export function landingPageViewCount(actions: unknown) {
  return actionValues(actions).get("landing_page_view") ?? 0;
}

export function normalizeMetaInsight(row: Record<string, unknown>): MetaInsight | null {
  const date = text(row.date_start);
  const campaignId = text(row.campaign_id);
  const adsetId = text(row.adset_id);
  const adId = text(row.ad_id);
  if (!date || !campaignId || !adsetId || !adId) return null;

  return {
    date,
    campaignId,
    campaignName: text(row.campaign_name) || campaignId,
    adsetId,
    adsetName: text(row.adset_name) || adsetId,
    adId,
    adName: text(row.ad_name) || adId,
    spend: nonNegative(row.spend),
    impressions: nonNegative(row.impressions),
    reach: nonNegative(row.reach),
    clicks: nonNegative(row.clicks),
    landingPageViews: landingPageViewCount(row.actions),
    platformLeads: platformLeadCount(row.actions),
  };
}

function actionValues(actions: unknown) {
  const values = new Map<string, number>();
  if (!Array.isArray(actions)) return values;

  for (const action of actions as MetaAction[]) {
    if (typeof action?.action_type !== "string") continue;
    const value = Number(action.value ?? 0);
    if (Number.isFinite(value) && value >= 0) values.set(action.action_type, value);
  }

  return values;
}

function text(value: unknown) {
  return typeof value === "string" ? value.trim() : "";
}

function nonNegative(value: unknown) {
  const number = Number(value ?? 0);
  return Number.isFinite(number) && number >= 0 ? number : 0;
}

