type MondayItem = { id: string; created_at: string; column_values: Array<{ id: string; text?: string | null; value?: string | null }> };

export class MondayConnector extends ServerOnlyConnector<MondayItem, NormalizedCrmLead> {
  provider = "monday" as const;
  constructor(private readonly mapping: MondayColumnMapping) { super(); }
  async fetch(): Promise<MondayItem[]> { this.requireSecret("MONDAY_CLIENT_ID"); throw new Error("Monday importer is prepared but not enabled until OAuth credentials, a board, and column mappings are selected."); }
  normalize(companyId: string, rows: MondayItem[]): NormalizedCrmLead[] {
    return rows.map((item) => { const values = new Map(item.column_values.map((column) => [column.id, column.text ?? column.value ?? undefined])); const get = (key: keyof MondayColumnMapping) => this.mapping[key] ? values.get(this.mapping[key] as string) : undefined; return { externalId: item.id, companyId, createdAt: item.created_at, salesperson: get("salesperson"), status: get("leadStatus"), qualification: get("qualification"), appointment: get("appointment"), quoteStatus: get("quoteStatus"), quoteAmount: numeric(get("quoteAmount")), outcome: get("outcome"), lostReason: get("lostReason"), projectValue: numeric(get("projectValue")) }; });
  }
}

function numeric(value: string | undefined) { if (!value) return undefined; const parsed = Number(value.replace(/[^0-9,.-]/g, "").replace(",", ".")); return Number.isFinite(parsed) ? parsed : undefined; }

import "server-only";
import { createHmac, randomBytes, timingSafeEqual } from "node:crypto";
import type { IntegrationProvider } from "./types";

type OAuthState = {
  companyId: string;
  provider: IntegrationProvider;
  userId: string;
  issuedAt: number;
  nonce: string;
};

export function createOAuthState(input: Omit<OAuthState, "issuedAt" | "nonce">) {
  const payload: OAuthState = { ...input, issuedAt: Date.now(), nonce: randomBytes(16).toString("hex") };
  const encoded = Buffer.from(JSON.stringify(payload)).toString("base64url");
  return `${encoded}.${signature(encoded)}`;
}

export function verifyOAuthState(value: string): OAuthState {
  const [encoded, supplied] = value.split(".");
  if (!encoded || !supplied) throw new Error("Invalid OAuth state.");
  const expected = signature(encoded);
  const suppliedBuffer = Buffer.from(supplied);
  const expectedBuffer = Buffer.from(expected);
  if (suppliedBuffer.length !== expectedBuffer.length || !timingSafeEqual(suppliedBuffer, expectedBuffer)) throw new Error("Invalid OAuth state.");
  const parsed = JSON.parse(Buffer.from(encoded, "base64url").toString("utf8")) as OAuthState;
  if (Date.now() - parsed.issuedAt > 10 * 60 * 1000) throw new Error("OAuth state has expired.");
  return parsed;
}

function signature(payload: string) {
  const secret = process.env.INTEGRATION_STATE_SECRET;
  if (!secret || secret.length < 32) throw new Error("INTEGRATION_STATE_SECRET must contain at least 32 characters.");
  return createHmac("sha256", secret).update(payload).digest("base64url");
}

import "server-only";

import { createHash, createHmac } from "node:crypto";
import type { ProviderCredential } from "./credentials";
import type { IntegrationProvider } from "./types";
import { providerCatalog } from "./catalog";
import { getGoogleAppConfig } from "./google/app-config";
import { fetchMetaPermissionState } from "./meta/client";
import { META_REQUIRED_PERMISSIONS } from "./meta/production-core";

const googleScopes = [
  "https://www.googleapis.com/auth/adwords",
  "https://www.googleapis.com/auth/analytics.readonly",
  "https://www.googleapis.com/auth/webmasters.readonly",
  "https://www.googleapis.com/auth/business.manage",
];

const metaScopes = [...META_REQUIRED_PERMISSIONS];

export async function buildAuthorizationUrl(
  provider: IntegrationProvider,
  redirectUri: string,
  state: string,
) {
  const group = providerCatalog[provider].authorizationGroup;

  if (group === "meta") {
    const url = new URL("https://www.facebook.com/v26.0/dialog/oauth");

    url.search = new URLSearchParams({
      client_id: required("META_APP_ID"),
      redirect_uri: redirectUri,
      response_type: "code",
      state,
      scope: metaScopes.join(","),
    }).toString();

    return url.toString();
  }

  if (group === "google") {
    const config = await getGoogleAppConfig();
    const url = new URL("https://accounts.google.com/o/oauth2/v2/auth");

    url.search = new URLSearchParams({
      client_id: config.clientId,
      redirect_uri: redirectUri,
      response_type: "code",
      state,
      scope: googleScopes.join(" "),
      access_type: "offline",
      prompt: "consent",
      include_granted_scopes: "true",
    }).toString();

    return url.toString();
  }

  if (group === "monday") {
    const verifier = mondayCodeVerifier(state);
    const challenge = createHash("sha256")
      .update(verifier)
      .digest("base64url");

    const url = new URL("https://auth.monday.com/oauth2/authorize");

    url.search = new URLSearchParams({
      client_id: required("MONDAY_CLIENT_ID"),
      redirect_uri: redirectUri,
      state,
      code_challenge: challenge,
      code_challenge_method: "S256",
    }).toString();

    return url.toString();
  }

  throw new Error(
    "Website forms use signed server-to-server ingestion, not OAuth.",
  );
}

export async function exchangeAuthorizationCode(
  provider: IntegrationProvider,
  code: string,
  redirectUri: string,
  state: string,
  existingCredential?: ProviderCredential | null,
): Promise<ProviderCredential> {
  const group = providerCatalog[provider].authorizationGroup;

  if (group === "google") {
    return exchangeGoogleCode(
      code,
      redirectUri,
      existingCredential,
    );
  }

  if (group === "monday") {
    return exchangeMondayCode(code, redirectUri, state);
  }

  if (group === "meta") {
    return exchangeMetaCode(code, redirectUri);
  }

  throw new Error("This provider does not use OAuth.");
}

async function exchangeGoogleCode(
  code: string,
  redirectUri: string,
  existingCredential?: ProviderCredential | null,
): Promise<ProviderCredential> {
  const config = await getGoogleAppConfig();
  const response = await fetch("https://oauth2.googleapis.com/token", {
    method: "POST",
    headers: {
      "Content-Type": "application/x-www-form-urlencoded",
    },
    body: new URLSearchParams({
      client_id: config.clientId,
      client_secret: config.clientSecret,
      code,
      grant_type: "authorization_code",
      redirect_uri: redirectUri,
    }),
    cache: "no-store",
  });

  const token = await tokenResponse(response, "Google");

  return {
    accessToken: token.access_token,
    refreshToken:
      token.refresh_token ??
      existingCredential?.refreshToken,
    expiresAt: expiresFromSeconds(token.expires_in),
    scopes: splitScopes(token.scope),
  };
}

async function exchangeMondayCode(
  code: string,
  redirectUri: string,
  state: string,
): Promise<ProviderCredential> {
  const response = await fetch(
    "https://auth.monday.com/oauth_ms/oauth/token",
    {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        grant_type: "authorization_code",
        client_id: required("MONDAY_CLIENT_ID"),
        client_secret: required("MONDAY_CLIENT_SECRET"),
        code,
        redirect_uri: redirectUri,
        code_verifier: mondayCodeVerifier(state),
      }),
      cache: "no-store",
    },
  );

  const token = await tokenResponse(response, "Monday");

  return {
    accessToken: token.access_token,
    refreshToken: token.refresh_token,
    expiresAt:
      expiresFromSeconds(token.expires_in) ??
      jwtExpiresAt(token.access_token),
    scopes: splitScopes(token.scope),
  };
}

async function exchangeMetaCode(
  code: string,
  redirectUri: string,
): Promise<ProviderCredential> {
  const shortResponse = await fetch(
    "https://graph.facebook.com/v26.0/oauth/access_token",
    {
      method: "POST",
      headers: {
        "Content-Type": "application/x-www-form-urlencoded",
      },
      body: new URLSearchParams({
        client_id: required("META_APP_ID"),
        client_secret: required("META_APP_SECRET"),
        redirect_uri: redirectUri,
        code,
      }),
      cache: "no-store",
    },
  );

  const shortToken = await tokenResponse(shortResponse, "Meta");

  const longResponse = await fetch(
    "https://graph.facebook.com/v26.0/oauth/access_token",
    {
      method: "POST",
      headers: {
        "Content-Type": "application/x-www-form-urlencoded",
      },
      body: new URLSearchParams({
        grant_type: "fb_exchange_token",
        client_id: required("META_APP_ID"),
        client_secret: required("META_APP_SECRET"),
        fb_exchange_token: shortToken.access_token,
      }),
      cache: "no-store",
    },
  );

  let token = shortToken;

  if (longResponse.ok) {
    token = await tokenResponse(longResponse, "Meta");
  }

  const permissions = await fetchMetaPermissionState(token.access_token);

  return {
    accessToken: token.access_token,
    expiresAt: expiresFromSeconds(token.expires_in),
    scopes: permissions.granted,
    permissionStatuses: permissions.statuses,
  };
}

function mondayCodeVerifier(state: string) {
  const secret = required("INTEGRATION_STATE_SECRET");

  return createHmac("sha256", secret)
    .update(`monday-pkce:${state}`)
    .digest("base64url");
}

type OAuthTokenResponse = {
  access_token: string;
  refresh_token?: string;
  expires_in?: number;
  scope?: string;
  token_type?: string;
};

async function tokenResponse(
  response: Response,
  provider: string,
): Promise<OAuthTokenResponse> {
  const body = await response.json().catch(() => ({})) as Record<
    string,
    unknown
  >;

  if (!response.ok) {
    const message =
      typeof body.error_description === "string"
        ? body.error_description
        : typeof body.error === "string"
          ? body.error
          : typeof body.message === "string"
            ? body.message
            : `${provider} returned HTTP ${response.status}`;

    throw new Error(`${provider} OAuth failed: ${message}`);
  }

  if (typeof body.access_token !== "string") {
    throw new Error(`${provider} OAuth response did not contain an access token.`);
  }

  return body as OAuthTokenResponse;
}

function expiresFromSeconds(seconds?: number) {
  if (!seconds || !Number.isFinite(seconds)) return undefined;

  return new Date(Date.now() + seconds * 1000).toISOString();
}

function jwtExpiresAt(token: string) {
  try {
    const [, payload] = token.split(".");
    if (!payload) return undefined;

    const parsed = JSON.parse(
      Buffer.from(payload, "base64url").toString("utf8"),
    ) as { exp?: number };

    if (!parsed.exp) return undefined;

    return new Date(parsed.exp * 1000).toISOString();
  } catch {
    return undefined;
  }
}

function splitScopes(scope?: string) {
  if (!scope) return [];

  return scope
    .split(/[ ,]+/)
    .map((value) => value.trim())
    .filter(Boolean);
}

function required(name: string) {
  const value = process.env[name];

  if (!value) {
    throw new Error(`Missing ${name}.`);
  }

  return value;
}

type RobawsPage<T> = {
  items?: T[];
  totalPages?: number;
  message?: string;
};

export type RobawsApiOptions = {
  credentials: {
    key: string;
    secret: string;
  };
  fetchImpl?: typeof fetch;
};

const baseUrl = "https://app.robaws.com/api/v2/";

export async function validateRobawsApi(options: RobawsApiOptions) {
  await Promise.all(
    ["clients", "offers", "projects", "sales-invoices"].map(
      path => robawsPage(path, { page: "0", size: "1" }, options),
    ),
  );
}

export async function fetchAllRobawsApi<T>(
  path: string,
  params: Record<string, string>,
  options: RobawsApiOptions,
): Promise<T[]> {
  const all: T[] = [];
  let page = 0;
  let totalPages = 1;

  do {
    const result = await robawsPage<T>(
      path,
      { ...params, page: String(page), size: "100" },
      options,
    );

    all.push(...(result.items ?? []));
    totalPages = Math.max(1, Number(result.totalPages ?? 1));
    page += 1;
  } while (page < totalPages);

  return all;
}

async function robawsPage<T = unknown>(
  path: string,
  params: Record<string, string>,
  options: RobawsApiOptions,
) {
  const url = new URL(path, baseUrl);

  for (const [key, value] of Object.entries(params)) {
    url.searchParams.set(key, value);
  }

  const { key, secret } = options.credentials;
  const response = await (options.fetchImpl ?? fetch)(url, {
    headers: {
      Authorization: `Basic ${Buffer.from(`${key}:${secret}`).toString("base64")}`,
      Accept: "application/json",
    },
    cache: "no-store",
  });

  const text = await response.text();
  const payload = parsePayload<T>(text);

  if (!response.ok) {
    const providerMessage =
      typeof payload.message === "string" && payload.message.trim()
        ? ` — ${sanitizeMessage(payload.message)}`
        : "";

    throw new Error(
      `ROBAWS ${path}: HTTP ${response.status}${providerMessage}`,
    );
  }

  return payload;
}

function parsePayload<T>(text: string): RobawsPage<T> {
  if (!text) return {};

  try {
    const value = JSON.parse(text) as unknown;
    return value && typeof value === "object"
      ? value as RobawsPage<T>
      : {};
  } catch {
    return { message: sanitizeMessage(text) };
  }
}

function sanitizeMessage(value: string) {
  return value.replace(/\s+/g, " ").trim().slice(0, 240);
}

import "server-only";

import {
  fetchAllRobawsApi,
  validateRobawsApi,
  type RobawsApiOptions,
} from "./robaws-client-core";

export function validateRobawsCredentials() {
  return validateRobawsApi(optionsFromEnvironment());
}

export function fetchAllRobaws<T>(
  path: string,
  params: Record<string, string> = {},
) {
  return fetchAllRobawsApi<T>(
    path,
    params,
    optionsFromEnvironment(),
  );
}

function optionsFromEnvironment(): RobawsApiOptions {
  const key = process.env.ROBAWS_API_KEY;
  const secret = process.env.ROBAWS_API_SECRET;

  if (!key || !secret) {
    throw new Error(
      "ROBAWS_API_KEY or ROBAWS_API_SECRET is missing.",
    );
  }

  return { credentials: { key, secret } };
}

import "server-only";

import { createSupabaseAdminClient } from "@/lib/supabase/admin";
import { fetchAllRobaws } from "@/lib/integrations/robaws-client";

